insert into public.courses (id, title, description, order_index) values ('066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid, '心理咨询过程与方法', '以助人技术三阶段模型为主线，系统学习咨询准备、探索、领悟、行动、整合与结束咨询。课程强调概念理解、技术意图、当事人反应和真实会谈中的灵活应用。', 6)
