咨询师发现一位当事人的经历与自己家人高度相似，自己在会谈中越来越想保护对方，并开始延长时间、频繁回复消息。请分析风险并提出处理方案。
## 📌 参考思路
参考要点：识别反移情触点和边界松动；评估是否影响专业判断与胜任力；恢复时间和联系设置；记录并接受督导；进行自我关照；以当事人利益为中心决定继续、调整或转介；不让当事人承担咨询师的个人需要。' where not exists (select 1 from public.chapter_review_notes where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid);
update public.chapter_review_notes set content = '# 【第三章 探索概述】
## 🎯 本章目标
理解探索阶段的目标、工作联盟和促进改变的关系条件，为内容与情感探索建立安全基础。
## 🧭 学习主线
说明探索目的 → 建立安全关系 → 邀请叙述 → 关注内容与情感 → 共同聚焦 → 检查体验与联盟。
---PAGE---
# 【探索阶段】
## 🧠 考试定义
帮助当事人讲述经验、觉察想法与情感、澄清问题并建立工作焦点的阶段。
## 💬 如何向来访者解释
这一阶段我们先把你的经历讲清楚，也会一起找出最需要工作的部分。
## 🧩 应用情境
初谈时允许当事人充分表达，同时逐渐形成可工作的主题。
## ⚠️ 易错点
把探索变成无边界聊天，或过早进入解释和行动。
---PAGE---
# 【共情理解】
## 🧠 考试定义
从当事人的参照框架理解其体验，并以可被检验的方式表达这种理解。
## 💬 如何向来访者解释
我会尽量从你的角度理解，如果我的理解不准确，请直接纠正我。
## 🧩 应用情境
用简洁回应核对“你既失望又担心被否定，是这样吗”。
## ⚠️ 易错点
把共情等同于同意、安慰或声称完全懂对方。
---PAGE---
# 【真诚一致】
## 🧠 考试定义
咨询师的内在体验、外在表达和专业角色保持适度一致，不用虚假姿态应对当事人。
## 💬 如何向来访者解释
如果我没听懂，我会诚实地请你再说明，而不会假装已经明白。
## 🧩 应用情境
不懂时承认需要澄清，而不是装作理解。
## ⚠️ 易错点
把真诚理解为想到什么就说什么，忽略当事人利益。
---PAGE---
# 【无条件积极关注】
## 🧠 考试定义
在不必赞同行为的前提下尊重当事人的人格价值和改变可能。
## 💬 如何向来访者解释
我可以不同意某个做法，但仍会尊重你，并和你一起理解它为什么发生。
## 🧩 应用情境
面对当事人的错误决定仍保持尊重，同时讨论后果。
## ⚠️ 易错点
把接纳当作赞同所有行为或取消必要边界。
---PAGE---
# 【当事人参照框架】
## 🧠 考试定义
当事人基于个人经历、文化和意义系统理解世界的独特视角。
## 💬 如何向来访者解释
重要的是这件事在你的经历里意味着什么，而不只是别人怎么看。
## 🧩 应用情境
先询问“这对你意味着什么”，再形成假设。
## ⚠️ 易错点
只用咨询师自己的常识解释当事人的反应。
---PAGE---
# 【探索焦点】
## 🧠 考试定义
从大量材料中共同选择与目标相关、情绪活跃且可工作的主题。
## 💬 如何向来访者解释
我们谈到几个重要方向，你更希望今天先从哪一个开始？
## 🧩 应用情境
当叙述分散时总结多个线索并请当事人选择先谈哪一个。
## ⚠️ 易错点
咨询师单方面决定重点，或同时追逐所有细节。
---PAGE---
# 【探索教育】
## 🧠 考试定义
向当事人说明探索的目的、方式和可能体验，以提升合作和可预测性。
## 💬 如何向来访者解释
接下来可能会更细地谈感受，如果太快或太难受，你可以随时告诉我。
## 🧩 应用情境
开始深层情感探索前说明可能会不舒服，也可随时放慢。
## ⚠️ 易错点
在没有说明的情况下突然追问敏感经历。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人不断讲述工作细节，却很少谈自己的感受。咨询师既担心会谈停留在表面，又不想强行推进。请设计探索阶段的回应。
## 📌 参考思路
参考要点：先共情并总结工作事件；说明探索目的；以试探语气邀请关注感受和意义；核对当事人是否愿意；从多个主题中共同选择焦点；尊重节奏并持续检查联盟，不直接解释或强迫暴露。' where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid;
insert into public.chapter_review_notes (course_id, chapter_id, content) select '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, '# 【第三章 探索概述】
