同一事件中同时存在方向不同或相互冲突的多种情绪。
## 💬 如何向来访者解释
对同一件事同时轻松和难过并不矛盾，我们可以分别理解它们。
## 🧩 应用情境
帮助当事人同时容纳对离开关系的轻松与悲伤。
## ⚠️ 易错点
要求当事人选出唯一“真实”情绪。
---PAGE---
# 【情感强度】
## 🧠 考试定义
情绪体验的程度、持续性和对功能的影响，需要用贴近当事人的词语和尺度核对。
## 💬 如何向来访者解释
如果0代表没有、10代表最强，现在大约是多少？
## 🧩 应用情境
询问0到10的强度，并区分烦躁、愤怒和暴怒。
## ⚠️ 易错点
使用过强情感词放大体验，或用过弱词淡化痛苦。
---PAGE---
# 【情感深化】
## 🧠 考试定义
在安全和联盟允许时，从表层情绪逐步接近更核心的需要、脆弱和意义。
## 💬 如何向来访者解释
我们可以稍微靠近这份愤怒下面的感受，但节奏由你决定。
## 🧩 应用情境
从愤怒进一步探索被忽视、受伤或害怕失去。
## ⚠️ 易错点
越深越好，不顾当事人的准备和情绪承受窗口。
---PAGE---
# 【情感调节窗口】
## 🧠 考试定义
当事人能够保持连接、思考和体验而不过度淹没或麻木的可工作唤起范围。
## 💬 如何向来访者解释
如果现在太强烈，我们先让身体稳定下来，再决定是否继续。
## 🧩 应用情境
出现明显失控或解离线索时先稳定、定向和放慢。
## ⚠️ 易错点
把强烈宣泄本身当作治疗目标，忽略安全与整合。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人笑着说“没什么，只是父亲去世后我终于自由了”，随后沉默并握紧双手。请说明咨询师如何使用情感探索技术。
## 📌 参考思路
参考要点：观察语言与非语言不一致；先用试探性的情感反映；允许混合情感并核对强度；探索自由、悲伤、内疚或害怕等可能意义；留意调节窗口，必要时稳定和放慢；不武断揭示、不强迫哭泣或宣泄。' where not exists (select 1 from public.chapter_review_notes where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid);
update public.chapter_review_notes set content = '# 【第六章 探索的拓展技术】
## 🎯 本章目标
在基础探索之上使用聚焦、沉默、即时性、适度自我表露、过程观察和高级共情，扩展当事人的觉察。
## 🧭 学习主线
确认联盟和节奏 → 选择需要深化的线索 → 使用拓展技术 → 观察当事人反应 → 回到当事人体验并共同修正。
---PAGE---
# 【聚焦】
## 🧠 考试定义
把注意力从宽泛叙述引向某个关键体验、关系或当下反应，以便深入工作。
## 💬 如何向来访者解释
这个“怕让人失望”反复出现，我们是否可以在这里多停留一会儿？
## 🧩 应用情境
从多个事件中选择反复出现的“怕让人失望”继续探索。
## ⚠️ 易错点
由咨询师凭兴趣选题，忽略当事人目标。
---PAGE---
# 【治疗性沉默】
## 🧠 考试定义
有目的地保留语言空间，让当事人感受、思考或组织表达。
## 💬 如何向来访者解释
我们可以安静一会儿，不必急着说；我会留在这里。
## 🧩 应用情境
当事人触及重要情绪后保持在场，不急于填满停顿。
## ⚠️ 易错点
所有沉默都有帮助，或用沉默惩罚、施压当事人。
---PAGE---
# 【即时性】
## 🧠 考试定义
关注咨询关系此时此刻正在发生的互动，并将其作为理解关系模式的材料。
## 💬 如何向来访者解释
你刚才担心我会失望，我想了解此刻你是怎样感受我们之间的关系的。
## 🧩 应用情境
当事人担心咨询师失望时，邀请讨论此刻如何看待咨询师。
## ⚠️ 易错点
把咨询师的不满直接宣泄给当事人。
---PAGE---
# 【自我表露】
## 🧠 考试定义
咨询师有选择地分享与当事人目标相关、负担较小且能促进工作的个人反应或经验。
## 💬 如何向来访者解释
听到你仍愿意尝试，我感到很受触动；这句话对你有什么影响？
## 🧩 应用情境
短暂表达对当事人努力的真实触动，然后迅速回到当事人。
## ⚠️ 易错点
为了拉近关系大量讲自己，要求当事人照顾咨询师感受。
---PAGE---
# 【过程观察】
## 🧠 考试定义
描述当事人在会谈中的表达方式、变化或互动模式，并邀请共同观察。
## 💬 如何向来访者解释
我注意到谈到需要帮助时你会笑着转开，这个观察对你有意义吗？
## 🧩 应用情境
指出每当谈到需要时当事人就转向玩笑，并询问其体验。
## ⚠️ 易错点
把观察包装成诊断或指责。
---PAGE---
# 【高级共情】
## 🧠 考试定义
在当事人已表达材料基础上，试探性连接未完全说出的意义、需要或模式。
## 💬 如何向来访者解释
我有一个不确定的理解：你似乎既渴望靠近，又担心靠近后被拒绝，是这样吗？
## 🧩 应用情境
把多次经历联系到“想靠近又怕被拒绝”的核心张力。
## ⚠️ 易错点
脱离证据进行深层解读，并要求当事人接受。
---PAGE---
# 【阻抗探索】
## 🧠 考试定义
把回避、迟到、沉默或任务未完成视为需要理解的保护和沟通信号，而非单纯不合作。
## 💬 如何向来访者解释
没有完成可能在告诉我们这个任务不合适或太难，我们一起看看发生了什么。
## 🧩 应用情境
好奇地询问任务没有完成的困难、担忧和意义。
## ⚠️ 易错点
给当事人贴“不配合”标签或用权力迫使服从。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人每次谈到亲密关系就开玩笑并快速换话题，本次又说“没什么可谈的”。请选择并组合拓展探索技术。
## 📌 参考思路
参考要点：先保持共情与安全；用过程观察描述开玩笑和转题；以聚焦邀请停留；可使用短暂沉默；以高级共情提出“靠近与被拒绝”的试探假设；必要时使用即时性探索此刻关系；把回避理解为保护，不指责。' where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = '135122a0-78e5-5789-b229-bc96a7904079'::uuid;
