# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人每次谈到亲密关系就开玩笑并快速换话题，本次又说“没什么可谈的”。请选择并组合拓展探索技术。
## 📌 参考思路
参考要点：先保持共情与安全；用过程观察描述开玩笑和转题；以聚焦邀请停留；可使用短暂沉默；以高级共情提出“靠近与被拒绝”的试探假设；必要时使用即时性探索此刻关系；把回避理解为保护，不指责。' where not exists (select 1 from public.chapter_review_notes where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = '135122a0-78e5-5789-b229-bc96a7904079'::uuid);
update public.chapter_review_notes set content = '# 【第七章 领悟阶段概述】
## 🎯 本章目标
理解领悟阶段如何通过合作形成新的视角、识别模式和理解关系，使探索材料转化为可用的意义。
## 🧭 学习主线
汇总探索材料 → 识别重复模式与冲突 → 提出可检验假设 → 邀请当事人修正 → 联系目标与改变可能。
---PAGE---
# 【领悟阶段】
## 🧠 考试定义
在探索基础上帮助当事人形成新的理解、发现模式和意义，并为行动建立方向的阶段。
## 💬 如何向来访者解释
我们会把前面谈到的线索放在一起，看看是否能形成一种新的理解。
## 🧩 应用情境
把不同关系中的相似反应联系起来，讨论其功能与代价。
## ⚠️ 易错点
把领悟理解为咨询师揭示唯一真相。
---PAGE---
# 【模式识别】
## 🧠 考试定义
识别想法、情感、行为和关系反应在不同情境中的重复结构。
## 💬 如何向来访者解释
这个“先离开以免被抛下”的方式似乎在几个场景都出现，你怎么看？
## 🧩 应用情境
发现当事人在工作和亲密关系中都通过先退出避免被拒绝。
## ⚠️ 易错点
只依据一次事件就宣布稳定人格模式。
---PAGE---
# 【新视角】
## 🧠 考试定义
对原有经验形成更完整、灵活且能促进改变的解释。
## 💬 如何向来访者解释
新的理解不是说你错了，而是看看原来的方式如何保护过你、现在又有什么代价。
## 🧩 应用情境
从“我太脆弱”转向“回避曾保护我，但现在限制了连接”。
## ⚠️ 易错点
用积极思考否认现实困难和痛苦。
---PAGE---
# 【领悟假设】
## 🧠 考试定义
咨询师依据材料提出的暂时性解释，需要与当事人共同检验和修正。
## 💬 如何向来访者解释
这只是一个暂时的猜想，你最有资格判断它是否贴近你的经验。
## 🧩 应用情境
使用“我有一个猜想”并询问符合程度和例外。
## ⚠️ 易错点
以专业权威要求当事人接受解释。
---PAGE---
# 【协同建构】
## 🧠 考试定义
咨询师与当事人共同形成意义，而不是单方提供答案。
## 💬 如何向来访者解释
我们把各自看到的线索放在一起，形成一个对你有用的理解。
## 🧩 应用情境
邀请当事人为模式命名、补充证据并寻找例外。
## ⚠️ 易错点
咨询师垄断解释，或完全不提供任何专业反馈。
---PAGE---
# 【领悟时机】
## 🧠 考试定义
在联盟、材料充分度和当事人情绪准备度允许时提出新的理解。
## 💬 如何向来访者解释
如果你愿意，我想把几个线索连起来提出一个初步理解。
## 🧩 应用情境
当事人已有多个相关例子并表现出好奇时再连接模式。
## ⚠️ 易错点
为了显示专业而过早解释，或一直等待完美时机不工作。
---PAGE---
# 【领悟的行动指向】
## 🧠 考试定义
有效领悟应能帮助当事人看到选择、目标或可尝试的新反应。
## 💬 如何向来访者解释
理解模式是开始，接下来我们还要看看你想怎样回应得不同。
## 🧩 应用情境
理解回避模式后讨论下一次如何识别并暂停旧反应。
## ⚠️ 易错点
把“知道原因”本身当作改变完成。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人逐渐发现自己在工作和亲密关系中都会先贬低别人再退出，以避免可能的拒绝。请说明如何在领悟阶段共同形成理解。
## 📌 参考思路
参考要点：汇总多情境证据并识别重复模式；提出暂时性、非定论的领悟假设；理解该模式过去的保护功能和当前代价；邀请当事人修正、寻找例外和文化意义；联系其关系目标，形成可进入行动阶段的方向。' where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = '325237dd-a658-54e8-8021-7686d933fcde'::uuid;
insert into public.chapter_review_notes (course_id, chapter_id, content) select '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, '# 【第七章 领悟阶段概述】
