把不同关系中的相似反应联系起来，讨论其功能与代价。
## ⚠️ 易错点
把领悟理解为咨询师揭示唯一真相。
---PAGE---
# 【模式识别】
## 🧠 考试定义
识别想法、情感、行为和关系反应在不同情境中的重复结构。
## 💬 如何向来访者解释
这个“先离开以免被抛下”的方式似乎在几个场景都出现，你怎么看？
## 🧩 应用情境
发现当事人在工作和亲密关系中都通过先退出避免被拒绝。
## ⚠️ 易错点
只依据一次事件就宣布稳定人格模式。
---PAGE---
# 【新视角】
## 🧠 考试定义
对原有经验形成更完整、灵活且能促进改变的解释。
## 💬 如何向来访者解释
新的理解不是说你错了，而是看看原来的方式如何保护过你、现在又有什么代价。
## 🧩 应用情境
从“我太脆弱”转向“回避曾保护我，但现在限制了连接”。
## ⚠️ 易错点
用积极思考否认现实困难和痛苦。
---PAGE---
# 【领悟假设】
## 🧠 考试定义
咨询师依据材料提出的暂时性解释，需要与当事人共同检验和修正。
## 💬 如何向来访者解释
这只是一个暂时的猜想，你最有资格判断它是否贴近你的经验。
## 🧩 应用情境
使用“我有一个猜想”并询问符合程度和例外。
## ⚠️ 易错点
以专业权威要求当事人接受解释。
---PAGE---
# 【协同建构】
## 🧠 考试定义
咨询师与当事人共同形成意义，而不是单方提供答案。
## 💬 如何向来访者解释
我们把各自看到的线索放在一起，形成一个对你有用的理解。
## 🧩 应用情境
邀请当事人为模式命名、补充证据并寻找例外。
## ⚠️ 易错点
咨询师垄断解释，或完全不提供任何专业反馈。
---PAGE---
# 【领悟时机】
## 🧠 考试定义
在联盟、材料充分度和当事人情绪准备度允许时提出新的理解。
## 💬 如何向来访者解释
如果你愿意，我想把几个线索连起来提出一个初步理解。
## 🧩 应用情境
当事人已有多个相关例子并表现出好奇时再连接模式。
## ⚠️ 易错点
为了显示专业而过早解释，或一直等待完美时机不工作。
---PAGE---
# 【领悟的行动指向】
## 🧠 考试定义
有效领悟应能帮助当事人看到选择、目标或可尝试的新反应。
## 💬 如何向来访者解释
理解模式是开始，接下来我们还要看看你想怎样回应得不同。
## 🧩 应用情境
理解回避模式后讨论下一次如何识别并暂停旧反应。
## ⚠️ 易错点
把“知道原因”本身当作改变完成。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人逐渐发现自己在工作和亲密关系中都会先贬低别人再退出，以避免可能的拒绝。请说明如何在领悟阶段共同形成理解。
## 📌 参考思路
参考要点：汇总多情境证据并识别重复模式；提出暂时性、非定论的领悟假设；理解该模式过去的保护功能和当前代价；邀请当事人修正、寻找例外和文化意义；联系其关系目标，形成可进入行动阶段的方向。' where not exists (select 1 from public.chapter_review_notes where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = '325237dd-a658-54e8-8021-7686d933fcde'::uuid);
update public.chapter_review_notes set content = '# 【第八章 促进觉察的技术】
## 🎯 本章目标
使用挑战、对质和不一致识别等技术，帮助当事人觉察言行、目标与结果之间的差距，同时维持共情和联盟。
## 🧭 学习主线
确认关系基础 → 描述可观察的不一致 → 说明关切而非评判 → 邀请当事人反应 → 修复联盟并深化理解。
---PAGE---
# 【挑战】
## 🧠 考试定义
以尊重和合作方式指出限制性信念、回避或不一致，促进当事人检验原有模式。
## 💬 如何向来访者解释
我想和你一起检验这个要求是否真的可行，而不是说服你接受我的答案。
## 🧩 应用情境
在充分共情后邀请当事人检查“必须让所有人满意”的现实性。
## ⚠️ 易错点
把挑战当辩论、训斥或证明咨询师正确。
---PAGE---
# 【不一致】
## 🧠 考试定义
当事人的言语、情感、行为、目标或结果之间存在可观察的差异。
## 💬 如何向来访者解释
你说不在乎，但身体似乎很紧张，我想知道这两部分怎样同时存在。
## 🧩 应用情境
指出“说不在乎”与明显紧张和反复确认之间的差距。
## ⚠️ 易错点
把任何复杂或混合反应都当作虚伪。
---PAGE---
# 【支持性对质】
## 🧠 考试定义
在尊重与共情基础上直接呈现差异及其影响，并邀请共同理解。
## 💬 如何向来访者解释
这个方式确实保护了你，同时似乎也让你更难靠近别人，我们可以一起看看。
## 🧩 应用情境
先肯定保护功能，再指出该方式与亲密目标冲突。
## ⚠️ 易错点
用羞辱、讽刺或权力压迫来制造改变。
---PAGE---
# 【信念检验】
## 🧠 考试定义
通过证据、逻辑、结果和例外检验绝对化或限制性信念。
## 💬 如何向来访者解释
我们不是要强迫你换想法，而是看看这个信念是否准确、是否对你有帮助。
## 🧩 应用情境
询问“所有人都必须满意”的证据、代价和例外。
## ⚠️ 易错点
用咨询师价值观直接替换当事人信念。
---PAGE---
# 【挑战时机】
## 🧠 考试定义
选择当事人可承受、关系足够稳定且材料较充分的时点进行挑战。
## 💬 如何向来访者解释
如果现在适合，我想指出一个可能有些不舒服的差异。
## 🧩 应用情境
当事人情绪稳定并已觉察矛盾时提出差异。
## ⚠️ 易错点
在危机、失控或联盟脆弱时连续强硬对质。
---PAGE---
# 【挑战后的反应】
## 🧠 考试定义
挑战后观察当事人的开放、防御、困惑、羞耻或关系撤退，并据此调整。
## 💬 如何向来访者解释
刚才的话似乎让你退了一下，我想先了解它对你的影响。
## 🧩 应用情境
当对方沉默退缩时先处理影响，而不是继续加压。
## ⚠️ 易错点
把防御视为挑战成功的证明。
---PAGE---
# 【挑战与共情平衡】
## 🧠 考试定义
既保持对当事人经验的理解，也不回避指出阻碍目标的模式。
## 💬 如何向来访者解释
我能理解你为什么这样保护自己，同时也想和你看看它现在带来的限制。
## 🧩 应用情境
用“既……又……”表达保护功能与改变代价。
## ⚠️ 易错点
只共情不碰困难，或只挑战不承接体验。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人说最重要的目标是改善伴侣关系，却连续三周拒绝任何沟通尝试，并解释“真正爱我的人应该自动懂我”。请设计一次支持性挑战。
## 📌 参考思路
参考要点：先共情其失望和被理解的需要；描述目标与行为的不一致；以合作方式检验“自动懂我”的信念；讨论该信念的证据、结果和例外；观察挑战后的羞耻或防御；邀请当事人形成自己的理解，不急于进入命令式行动。' where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid;
insert into public.chapter_review_notes (course_id, chapter_id, content) select '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, '# 【第八章 促进觉察的技术】
