参考要点：认可改变愿望但评估信心、风险和资源；把全或无目标具体化；生成多个练习方案；从低风险关系和小请求开始；明确时间、行为和反馈记录；讨论失败与复发；由当事人选择，不以咨询师命令替代合作。' where not exists (select 1 from public.chapter_review_notes where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid);
update public.chapter_review_notes set content = '# 【第十三章 完成行动任务的步骤】
## 🎯 本章目标
掌握目标设定、方案探索、技能训练、实施计划、障碍处理和结果评估等完成行动任务的系统步骤。
## 🧭 学习主线
明确问题和目标 → 生成方案 → 选择方案 → 教学与示范 → 演练反馈 → 制定实施计划 → 评估并巩固。
---PAGE---
# 【行为目标化】
## 🧠 考试定义
把改变愿望转化为具体情境中的可观察行为、频率和完成标准。
## 💬 如何向来访者解释
我们把目标写成具体行为，这样你知道什么时候算迈出了一步。
## 🧩 应用情境
将“少焦虑”改为“焦虑时完成三分钟呼吸并继续停留五分钟”。
## ⚠️ 易错点
只使用抽象感受词，无法判断进展。
---PAGE---
# 【技能教学】
## 🧠 考试定义
向当事人清楚说明技能原理、步骤、适用情境和限制。
## 💬 如何向来访者解释
我会先说明这项技能为什么有用、怎样做，再由你判断是否适合。
## 🧩 应用情境
教授表达请求时先解释结构，再示范。
## ⚠️ 易错点
只告诉当事人“要沟通”，却不教怎么做。
---PAGE---
# 【示范】
## 🧠 考试定义
咨询师或材料展示目标技能的具体表现，为学习提供可观察样例。
## 💬 如何向来访者解释
这是一个示例，你可以调整成符合自己语言和文化的方式。
## 🧩 应用情境
示范一次坚定而尊重的拒绝。
## ⚠️ 易错点
让当事人机械模仿咨询师风格。
---PAGE---
# 【角色演练】
## 🧠 考试定义
在安全环境中模拟真实情境，练习新技能并观察困难。
## 💬 如何向来访者解释
我们先在这里试一遍，出错正好能帮助找到需要调整的地方。
## 🧩 应用情境
咨询师扮演上司，与当事人演练表达不同意见。
## ⚠️ 易错点
演练一次不顺就认定技能无效。
---PAGE---
# 【行为反馈】
## 🧠 考试定义
基于可观察行为提供具体、平衡且可操作的改进信息。
## 💬 如何向来访者解释
我会具体说哪些行为有效、下一次可以调整什么。
## 🧩 应用情境
先指出清晰表达，再建议放慢语速和补充请求。
## ⚠️ 易错点
只说“很好”或全面批评人格。
---PAGE---
# 【实施意图】
## 🧠 考试定义
用“如果出现情境X，我就执行行为Y”把行动与明确线索连接。
## 💬 如何向来访者解释
我们把计划写成“如果……那么……”，让行动更容易启动。
## 🧩 应用情境
设定“如果会议中出现不同意见，我先深呼吸再表达一句观点”。
## ⚠️ 易错点
只靠意志和模糊提醒，不指定触发与行为。
---PAGE---
# 【障碍预演】
## 🧠 考试定义
提前识别可能阻碍行动的情境、情绪和想法，并准备替代方案。
## 💬 如何向来访者解释
提前想到困难不是泼冷水，而是在为真实生活做准备。
## 🧩 应用情境
预演被拒绝、忘记或情绪升高时如何调整。
## ⚠️ 易错点
把障碍理解为消极，不允许讨论失败可能。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人想在下周向上司提出工作边界，但过去一紧张就沉默。请按行动任务步骤设计会谈内训练和会谈外实施。
## 📌 参考思路
参考要点：将目标具体化；说明表达边界技能；咨询师示范并让当事人角色演练；提供具体反馈并重复练习；设置“如果—那么”实施意图；预演上司拒绝和紧张升高；确定时间、支持与记录；下次根据结果调整。' where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid;
insert into public.chapter_review_notes (course_id, chapter_id, content) select '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, '# 【第十三章 完成行动任务的步骤】
## 🎯 本章目标
掌握目标设定、方案探索、技能训练、实施计划、障碍处理和结果评估等完成行动任务的系统步骤。
## 🧭 学习主线
明确问题和目标 → 生成方案 → 选择方案 → 教学与示范 → 演练反馈 → 制定实施计划 → 评估并巩固。
---PAGE---
# 【行为目标化】
## 🧠 考试定义
把改变愿望转化为具体情境中的可观察行为、频率和完成标准。
## 💬 如何向来访者解释
我们把目标写成具体行为，这样你知道什么时候算迈出了一步。
## 🧩 应用情境
将“少焦虑”改为“焦虑时完成三分钟呼吸并继续停留五分钟”。
## ⚠️ 易错点
只使用抽象感受词，无法判断进展。
---PAGE---
# 【技能教学】
## 🧠 考试定义
向当事人清楚说明技能原理、步骤、适用情境和限制。
## 💬 如何向来访者解释
我会先说明这项技能为什么有用、怎样做，再由你判断是否适合。
## 🧩 应用情境
教授表达请求时先解释结构，再示范。
## ⚠️ 易错点
只告诉当事人“要沟通”，却不教怎么做。
---PAGE---
# 【示范】
## 🧠 考试定义
咨询师或材料展示目标技能的具体表现，为学习提供可观察样例。
## 💬 如何向来访者解释
这是一个示例，你可以调整成符合自己语言和文化的方式。
## 🧩 应用情境
示范一次坚定而尊重的拒绝。
## ⚠️ 易错点
让当事人机械模仿咨询师风格。
---PAGE---
# 【角色演练】
## 🧠 考试定义
在安全环境中模拟真实情境，练习新技能并观察困难。
## 💬 如何向来访者解释
我们先在这里试一遍，出错正好能帮助找到需要调整的地方。
## 🧩 应用情境
咨询师扮演上司，与当事人演练表达不同意见。
## ⚠️ 易错点
演练一次不顺就认定技能无效。
---PAGE---
# 【行为反馈】
## 🧠 考试定义
基于可观察行为提供具体、平衡且可操作的改进信息。
## 💬 如何向来访者解释
我会具体说哪些行为有效、下一次可以调整什么。
## 🧩 应用情境
先指出清晰表达，再建议放慢语速和补充请求。
## ⚠️ 易错点
只说“很好”或全面批评人格。
---PAGE---
