---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人想在下周向上司提出工作边界，但过去一紧张就沉默。请按行动任务步骤设计会谈内训练和会谈外实施。
## 📌 参考思路
参考要点：将目标具体化；说明表达边界技能；咨询师示范并让当事人角色演练；提供具体反馈并重复练习；设置“如果—那么”实施意图；预演上司拒绝和紧张升高；确定时间、支持与记录；下次根据结果调整。' where not exists (select 1 from public.chapter_review_notes where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid);
update public.chapter_review_notes set content = '# 【第十四章 行动阶段技术整合】
## 🎯 本章目标
整合教学、建议、示范、演练、反馈、家庭任务和环境支持，使行动既符合当事人自主性又具有可执行性。
## 🧭 学习主线
确认目标与自主性 → 选择适合的行动技术 → 会谈内学习演练 → 会谈外任务 → 结果反馈 → 调整并巩固。
---PAGE---
# 【技术整合】
## 🧠 考试定义
围绕同一行动目标组合多种互补技术，而不是堆叠无关方法。
## 💬 如何向来访者解释
我们只选择真正服务于目标的几种方法，并根据你的反应调整。
## 🧩 应用情境
为表达边界组合教学、示范、演练和家庭任务。
## ⚠️ 易错点
技术越多越好，忽略目标和学习负荷。
---PAGE---
# 【合作式建议】
## 🧠 考试定义
在征得同意后提供基于目标的可选方案，并保留当事人的决定权。
## 💬 如何向来访者解释
我可以提供一个选项，你可以决定是否采用或怎样修改。
## 🧩 应用情境
询问“你愿意听一个可能方案吗”，再讨论适配性。
## ⚠️ 易错点
用专家身份直接命令，或暗示拒绝建议就是不配合。
---PAGE---
# 【家庭任务】
## 🧠 考试定义
把会谈中的学习带入真实生活的具体练习，并在后续共同回顾。
## 💬 如何向来访者解释
任务是一次实验，不是考试；没完成也能帮助我们理解障碍。
## 🧩 应用情境
任务难度、时间和记录方式由双方共同设定。
## ⚠️ 易错点
布置与目标无关、难度过高的作业，未完成就批评。
---PAGE---
# 【环境支持】
## 🧠 考试定义
通过改变提示、资源、社会支持或情境安排提高行动成功率。
## 💬 如何向来访者解释
改变不只靠意志，我们也可以调整环境，让新行为更容易发生。
## 🧩 应用情境
请可信任的人提醒，或提前准备书面要点。
## ⚠️ 易错点
只要求当事人增强意志力，忽略环境限制。
---PAGE---
# 【技能迁移】
## 🧠 考试定义
把会谈中学到的技能应用到不同对象和情境，并逐渐减少依赖。
## 💬 如何向来访者解释
我们会从较容易的场景开始，再逐步迁移到更困难的场景。
## 🧩 应用情境
从咨询室演练迁移到朋友、同事和高难度关系。
## ⚠️ 易错点
在一个情境成功就认为所有场景都会自动成功。
---PAGE---
# 【行动复盘】
## 🧠 考试定义
比较计划、实际行为、结果和学习，识别有效因素与需要调整部分。
## 💬 如何向来访者解释
我们不仅看有没有完成，还看发生了什么、学到了什么。
## 🧩 应用情境
区分任务未完成是目标、技能、情绪还是环境问题。
## ⚠️ 易错点
复盘只问“做没做”，不分析过程。
---PAGE---
# 【自主性保护】
## 🧠 考试定义
确保行动目标和选择属于当事人，咨询师提供结构与资源但不接管人生决定。
## 💬 如何向来访者解释
你有权决定是否做、做多少；我的角色是帮助你看清选择和后果。
## 🧩 应用情境
当事人拒绝建议时探索原因并重新协商。
## ⚠️ 易错点
把顺从当成进步，把不同意当成阻抗。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
当事人没有完成家庭任务，解释说任务像“咨询师布置的作业”，自己越想越抗拒。请用行动阶段整合原则处理。
## 📌 参考思路
参考要点：不把未完成视为失败；探索任务是否缺乏自主性、难度过高或不符合价值；承认咨询师可能过度主导；重新确认目标；征得同意后共同生成方案；减小任务并增加环境支持；明确任务是实验并约定复盘。' where course_id = '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid and chapter_id = 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid;
insert into public.chapter_review_notes (course_id, chapter_id, content) select '066e7a57-7d3e-5e45-988c-9bdf6c11ada1'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, '# 【第十四章 行动阶段技术整合】
