insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ad00c053-c863-528d-8941-9e67ffaab54a'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'single', '会谈情境：询问家庭、地域、性别、阶层或信仰对问题的意义，而不按标签推断。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"自我关照"},{"key":"B","text":"专业胜任力"},{"key":"C","text":"自我觉察"},{"key":"D","text":"文化谦逊"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境体现“文化谦逊”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
