insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('7a2693b8-72e5-5069-a3ff-6d1bc1da51a1'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'single', '会谈情境：在咨询开始前说明联系渠道、会谈时间和紧急情况处理。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"专业边界"},{"key":"B","text":"专业胜任力"},{"key":"C","text":"自我觉察"},{"key":"D","text":"反移情触点"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境体现“专业边界”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
