insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('eb76164f-e0ad-501b-b2b1-4cd470894c87'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'single', '咨询师向来访者说明：“为保证服务质量，我会在保护你隐私的前提下接受专业督导。”这段说明主要对应哪一项技术或原则？', '[{"key":"A","text":"自我觉察"},{"key":"B","text":"督导"},{"key":"C","text":"反移情触点"},{"key":"D","text":"文化谦逊"}]'::jsonb, '{"correct":"B"}'::jsonb, '这段面向来访者的说明对应“督导”，重点是能否以合作、易懂的方式解释技术意图。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('feacd247-953d-5753-a9d4-94fcf67439f3'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'single', '围绕“自我关照”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"出现耗竭、共情疲劳或注意力下降时减少负荷并寻求支持。"},{"key":"B","text":"把自我牺牲当成专业奉献，忽视耗竭对当事人的风险。"},{"key":"C","text":"依据概念进行判断：咨询师通过休息、支持、界限、反思和专业资源维持稳定工作能力。"},{"key":"D","text":"向来访者说明：咨询师保持稳定也是服务质量的一部分，我会负责任地管理自己的工作状态。"}]'::jsonb, '{"correct":"B"}'::jsonb, '应避免：把自我牺牲当成专业奉献，忽视耗竭对当事人的风险。。规范依据是：咨询师通过休息、支持、界限、反思和专业资源维持稳定工作能力。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('04d79da2-baaf-5b30-91be-be02fb4be356'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'multi', '从技术操作是否规范的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"遇到不熟悉的高风险问题时先咨询督导并考虑转介。"},{"key":"B","text":"我会留意自己的反应，确保它们服务于你的需要，而不是把我的价值观放到你身上。"},{"key":"C","text":"把强烈反应直接当作关于当事人的客观事实。"},{"key":"D","text":"掌握几条文化知识后就自认为完全理解某一群体。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“专业胜任力”的规范应用，B体现向来访者说明“自我觉察”时的合作性表达；C、D分别是“反移情触点”和“文化谦逊”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('da9e99f5-f1db-523c-96f4-bee51340b66c'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'multi', '从合作性和来访者体验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"对某类当事人异常保护或厌烦时，通过记录和督导理解反应。"},{"key":"B","text":"你的文化和生活经验可能影响你怎么看这件事，我希望由你告诉我它对你的意义。"},{"key":"C","text":"把边界理解为冷漠，或为表示关心而随意突破设置。"},{"key":"D","text":"只在犯错后接受检查，或把督导当作替自己做决定。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“反移情触点”的规范应用，B体现向来访者说明“文化谦逊”时的合作性表达；C、D分别是“专业边界”和“督导”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('480a5b98-2ec0-583c-87f0-f5e33f2f26e0'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'multi', '从技术时机、边界与效果检验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"在咨询开始前说明联系渠道、会谈时间和紧急情况处理。"},{"key":"B","text":"为保证服务质量，我会在保护你隐私的前提下接受专业督导。"},{"key":"C","text":"把自我牺牲当成专业奉献，忽视耗竭对当事人的风险。"},{"key":"D","text":"仅凭热情或个人经历就处理超出训练范围的问题。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“专业边界”的规范应用，B体现向来访者说明“督导”时的合作性表达；C、D分别是“自我关照”和“专业胜任力”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9cae6b21-8b3e-5f5d-a9a4-1cbe01f44a0f'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'blank', '请依据本章学习主线补全工作流程：检查胜任力与状态 → ____ → 理解文化情境 → 明确边界 → 使用督导并持续自我关照。', NULL, '{"correct":["识别个人触点和偏见"]}'::jsonb, '本章流程中该环节是“识别个人触点和偏见”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
