insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('574ca6e6-b61c-5c3f-9aa6-2544a60bcbb0'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'blank', '请依据本章学习主线补全工作流程：检查胜任力与状态 → 识别个人触点和偏见 → 理解文化情境 → 明确边界 → ____。', NULL, '{"correct":["使用督导并持续自我关照"]}'::jsonb, '本章流程中该环节是“使用督导并持续自我关照”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b5523d23-e5b3-53a4-9369-14ab5d68e3ba'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'short', '简答题：咨询师的准备包含哪些主要技术或核心要点？请列举并说明这些内容如何共同服务本章目标。', NULL, '{"reference":"参考要点：\n1）主要技术或核心要点包括：专业胜任力、自我觉察、反移情触点、文化谦逊、专业边界、督导、自我关照。\n2）本章目标：从专业胜任力、自我觉察、文化谦逊、伦理边界、督导和自我关照等方面准备进入助人工作。\n3）作答不能只罗列名称，还应依据“检查胜任力与状态 → 识别个人触点和偏见 → 理解文化情境 → 明确边界 → 使用督导并持续自我关照。”说明各项技术在工作流程中的位置、目的与衔接关系。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('2c492326-e90f-56cb-8816-bb125b46e4b8'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'short', '简答题：说明“专业胜任力”与“文化谦逊”各自的含义，并指出在咨询师的准备中的应用要点。', NULL, '{"reference":"参考要点：\n1）专业胜任力：咨询师在教育训练、知识、技能和经验范围内提供服务，并持续维护专业能力。\n2）文化谦逊：持续承认自身知识有限，主动了解当事人的文化身份、权力位置和独特意义。\n3）应用：遇到不熟悉的高风险问题时先咨询督导并考虑转介。\n4）应用：询问家庭、地域、性别、阶层或信仰对问题的意义，而不按标签推断。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('297ba55f-c47b-51f5-a08d-23aff952350e'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'short', '简答题：如果来访者询问“为什么要使用专业边界和督导”，咨询师应如何用易懂、合作且不过度承诺的方式说明？', NULL, '{"reference":"参考要点：\n1）专业边界：清楚的边界能让关系更安全，也让你知道什么时候、用什么方式可以联系我。\n2）督导：为保证服务质量，我会在保护你隐私的前提下接受专业督导。\n3）说明技术目的和选择理由，并邀请来访者表达是否符合其需要。\n4）避免专业权威式断言，也不承诺技术一定产生某种结果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('807e51e8-7aa3-5d83-8265-2ddddef662e8'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'case', '案例题：咨询师发现一位当事人的经历与自己家人高度相似，自己在会谈中越来越想保护对方，并开始延长时间、频繁回复消息。请分析风险并提出处理方案。', NULL, '{"reference":"参考要点：识别反移情触点和边界松动；评估是否影响专业判断与胜任力；恢复时间和联系设置；记录并接受督导；进行自我关照；以当事人利益为中心决定继续、调整或转介；不让当事人承担咨询师的个人需要。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('6efe6c70-7361-5a1f-803f-5816245010dc'::uuid, 'd407d8b6-0abb-5896-b785-ea3deaef79e4'::uuid, 'case', '案例题：咨询师在使用“自我关照”时采用了以下做法：“把自我牺牲当成专业奉献，忽视耗竭对当事人的风险。”请指出问题，改写为更规范的处理，并说明如何检查来访者的反应。', NULL, '{"reference":"参考要点：该做法把“自我关照”使用成了常见误区。规范依据是：咨询师通过休息、支持、界限、反思和专业资源维持稳定工作能力。可改为：出现耗竭、共情疲劳或注意力下降时减少负荷并寻求支持；向来访者说明时可表达为：“咨询师保持稳定也是服务质量的一部分，我会负责任地管理自己的工作状态。”随后应邀请来访者反馈贴合度、情绪反应和是否愿意继续，并根据反馈调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a4c9fb58-6cd3-574c-b7de-a860244308f1'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'single', '下列哪一概念最符合这一描述：“帮助当事人讲述经验、觉察想法与情感、澄清问题并建立工作焦点的阶段。”？', '[{"key":"A","text":"探索阶段"},{"key":"B","text":"真诚一致"},{"key":"C","text":"无条件积极关注"},{"key":"D","text":"当事人参照框架"}]'::jsonb, '{"correct":"A"}'::jsonb, '该描述对应“探索阶段”。应用提示：初谈时允许当事人充分表达，同时逐渐形成可工作的主题。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b3d93cc4-6e71-5a0c-a798-b62f3f152fee'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'single', '下列哪一概念最符合这一描述：“从当事人的参照框架理解其体验，并以可被检验的方式表达这种理解。”？', '[{"key":"A","text":"无条件积极关注"},{"key":"B","text":"共情理解"},{"key":"C","text":"当事人参照框架"},{"key":"D","text":"探索焦点"}]'::jsonb, '{"correct":"B"}'::jsonb, '该描述对应“共情理解”。应用提示：用简洁回应核对“你既失望又担心被否定，是这样吗”。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c3c1c998-c010-543a-b04a-42f17a3bd61c'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'single', '会谈情境：不懂时承认需要澄清，而不是装作理解。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"探索焦点"},{"key":"B","text":"探索教育"},{"key":"C","text":"真诚一致"},{"key":"D","text":"探索阶段"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境体现“真诚一致”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
