insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('4ef8131a-eb37-523e-a6df-24f01920d654'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'single', '会谈情境：面对当事人的错误决定仍保持尊重，同时讨论后果。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"探索教育"},{"key":"B","text":"探索阶段"},{"key":"C","text":"共情理解"},{"key":"D","text":"无条件积极关注"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境体现“无条件积极关注”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
