insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('4cd9b6d9-9f36-5901-816e-88f7ffebd53e'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'single', '会谈情境：先询问“这对你意味着什么”，再形成假设。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"当事人参照框架"},{"key":"B","text":"探索阶段"},{"key":"C","text":"共情理解"},{"key":"D","text":"真诚一致"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境体现“当事人参照框架”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('13860bc7-5fb6-52f5-972f-0164e57d7046'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'single', '咨询师向来访者说明：“我们谈到几个重要方向，你更希望今天先从哪一个开始？”这段说明主要对应哪一项技术或原则？', '[{"key":"A","text":"共情理解"},{"key":"B","text":"探索焦点"},{"key":"C","text":"真诚一致"},{"key":"D","text":"无条件积极关注"}]'::jsonb, '{"correct":"B"}'::jsonb, '这段面向来访者的说明对应“探索焦点”，重点是能否以合作、易懂的方式解释技术意图。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c62f78db-5221-5836-8dc2-5c5a0b7b32a8'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'single', '围绕“探索教育”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"开始深层情感探索前说明可能会不舒服，也可随时放慢。"},{"key":"B","text":"依据概念进行判断：向当事人说明探索的目的、方式和可能体验，以提升合作和可预测性。"},{"key":"C","text":"在没有说明的情况下突然追问敏感经历。"},{"key":"D","text":"向来访者说明：接下来可能会更细地谈感受，如果太快或太难受，你可以随时告诉我。"}]'::jsonb, '{"correct":"C"}'::jsonb, '应避免：在没有说明的情况下突然追问敏感经历。。规范依据是：向当事人说明探索的目的、方式和可能体验，以提升合作和可预测性。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1c1ba23a-d0be-50d7-ae32-9ad7377f3649'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'multi', '从技术操作是否规范的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"初谈时允许当事人充分表达，同时逐渐形成可工作的主题。"},{"key":"B","text":"我会尽量从你的角度理解，如果我的理解不准确，请直接纠正我。"},{"key":"C","text":"把真诚理解为想到什么就说什么，忽略当事人利益。"},{"key":"D","text":"把接纳当作赞同所有行为或取消必要边界。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“探索阶段”的规范应用，B体现向来访者说明“共情理解”时的合作性表达；C、D分别是“真诚一致”和“无条件积极关注”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('31eb0247-8510-5872-9cec-c7c036c76aae'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'multi', '从合作性和来访者体验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"不懂时承认需要澄清，而不是装作理解。"},{"key":"B","text":"我可以不同意某个做法，但仍会尊重你，并和你一起理解它为什么发生。"},{"key":"C","text":"只用咨询师自己的常识解释当事人的反应。"},{"key":"D","text":"咨询师单方面决定重点，或同时追逐所有细节。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“真诚一致”的规范应用，B体现向来访者说明“无条件积极关注”时的合作性表达；C、D分别是“当事人参照框架”和“探索焦点”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ef0b5d3c-1413-530d-bd69-7763e2a943db'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'multi', '从技术时机、边界与效果检验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"先询问“这对你意味着什么”，再形成假设。"},{"key":"B","text":"我们谈到几个重要方向，你更希望今天先从哪一个开始？"},{"key":"C","text":"在没有说明的情况下突然追问敏感经历。"},{"key":"D","text":"把探索变成无边界聊天，或过早进入解释和行动。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“当事人参照框架”的规范应用，B体现向来访者说明“探索焦点”时的合作性表达；C、D分别是“探索教育”和“探索阶段”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9a6c3d88-ad28-559c-a78a-a4aa15b4ce83'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'blank', '请依据本章学习主线补全工作流程：说明探索目的 → ____ → 邀请叙述 → 关注内容与情感 → 共同聚焦 → 检查体验与联盟。', NULL, '{"correct":["建立安全关系"]}'::jsonb, '本章流程中该环节是“建立安全关系”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c7a30cff-006a-5d3a-a89c-60e9afad8684'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'blank', '请依据本章学习主线补全工作流程：说明探索目的 → 建立安全关系 → 邀请叙述 → ____ → 共同聚焦 → 检查体验与联盟。', NULL, '{"correct":["关注内容与情感"]}'::jsonb, '本章流程中该环节是“关注内容与情感”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c2a9fcbe-fd5a-50d3-af16-ccc099d469d8'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'blank', '请依据本章学习主线补全工作流程：说明探索目的 → 建立安全关系 → 邀请叙述 → 关注内容与情感 → 共同聚焦 → ____。', NULL, '{"correct":["检查体验与联盟"]}'::jsonb, '本章流程中该环节是“检查体验与联盟”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c4199649-e200-5f6e-904f-226d3462571a'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'short', '简答题：探索概述包含哪些主要技术或核心要点？请列举并说明这些内容如何共同服务本章目标。', NULL, '{"reference":"参考要点：\n1）主要技术或核心要点包括：探索阶段、共情理解、真诚一致、无条件积极关注、当事人参照框架、探索焦点、探索教育。\n2）本章目标：理解探索阶段的目标、工作联盟和促进改变的关系条件，为内容与情感探索建立安全基础。\n3）作答不能只罗列名称，还应依据“说明探索目的 → 建立安全关系 → 邀请叙述 → 关注内容与情感 → 共同聚焦 → 检查体验与联盟。”说明各项技术在工作流程中的位置、目的与衔接关系。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('72d59982-243b-5842-9cb1-c9a478f4143c'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'short', '简答题：说明“探索阶段”与“无条件积极关注”各自的含义，并指出在探索概述中的应用要点。', NULL, '{"reference":"参考要点：\n1）探索阶段：帮助当事人讲述经验、觉察想法与情感、澄清问题并建立工作焦点的阶段。\n2）无条件积极关注：在不必赞同行为的前提下尊重当事人的人格价值和改变可能。\n3）应用：初谈时允许当事人充分表达，同时逐渐形成可工作的主题。\n4）应用：面对当事人的错误决定仍保持尊重，同时讨论后果。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('dea96b05-5355-5882-bc07-31e4c5ea380d'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'short', '简答题：如果来访者询问“为什么要使用当事人参照框架和探索焦点”，咨询师应如何用易懂、合作且不过度承诺的方式说明？', NULL, '{"reference":"参考要点：\n1）当事人参照框架：重要的是这件事在你的经历里意味着什么，而不只是别人怎么看。\n2）探索焦点：我们谈到几个重要方向，你更希望今天先从哪一个开始？\n3）说明技术目的和选择理由，并邀请来访者表达是否符合其需要。\n4）避免专业权威式断言，也不承诺技术一定产生某种结果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('22e4e014-4004-58c8-8590-b6bd7553bbac'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'case', '案例题：当事人不断讲述工作细节，却很少谈自己的感受。咨询师既担心会谈停留在表面，又不想强行推进。请设计探索阶段的回应。', NULL, '{"reference":"参考要点：先共情并总结工作事件；说明探索目的；以试探语气邀请关注感受和意义；核对当事人是否愿意；从多个主题中共同选择焦点；尊重节奏并持续检查联盟，不直接解释或强迫暴露。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f21ac830-8730-5411-ba78-0304d81a8afa'::uuid, '1902819a-6cb6-50e0-8847-6680e780baf4'::uuid, 'case', '案例题：咨询师在使用“探索教育”时采用了以下做法：“在没有说明的情况下突然追问敏感经历。”请指出问题，改写为更规范的处理，并说明如何检查来访者的反应。', NULL, '{"reference":"参考要点：该做法把“探索教育”使用成了常见误区。规范依据是：向当事人说明探索的目的、方式和可能体验，以提升合作和可预测性。可改为：开始深层情感探索前说明可能会不舒服，也可随时放慢；向来访者说明时可表达为：“接下来可能会更细地谈感受，如果太快或太难受，你可以随时告诉我。”随后应邀请来访者反馈贴合度、情绪反应和是否愿意继续，并根据反馈调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('292c6d7c-13ef-544d-a2cc-eefe4064a569'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'single', '下列哪一概念最符合这一描述：“用更简洁的语言表达当事人刚才陈述的核心内容，以确认理解并促进继续探索。”？', '[{"key":"A","text":"重述"},{"key":"B","text":"封闭式提问"},{"key":"C","text":"最小鼓励"},{"key":"D","text":"澄清"}]'::jsonb, '{"correct":"A"}'::jsonb, '该描述对应“重述”。应用提示：当事人说了长段经历后，咨询师抓住关键事件和意义重新表达。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f3fad161-89e6-5bee-8fec-dfc0ca08136b'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'single', '下列哪一概念最符合这一描述：“邀请当事人用较自由、丰富的方式叙述经验，通常不能只用是或否回答。”？', '[{"key":"A","text":"最小鼓励"},{"key":"B","text":"开放式提问"},{"key":"C","text":"澄清"},{"key":"D","text":"总结"}]'::jsonb, '{"correct":"B"}'::jsonb, '该描述对应“开放式提问”。应用提示：使用“那件事发生后你有哪些反应”扩展信息。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b0517342-7306-51d4-82a0-a857b549520e'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'single', '会谈情境：核对时间、频率、风险和设置等必要事实。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"总结"},{"key":"B","text":"结构化"},{"key":"C","text":"封闭式提问"},{"key":"D","text":"重述"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境体现“封闭式提问”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('8979ce7d-42ed-5fe8-a7a6-164b1ace3c97'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'single', '会谈情境：在当事人停顿但仍在思考时，用“嗯”“然后呢”保持空间。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"结构化"},{"key":"B","text":"重述"},{"key":"C","text":"开放式提问"},{"key":"D","text":"最小鼓励"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境体现“最小鼓励”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9c2ed0eb-c309-55bd-9c8b-0485d2c23f86'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'single', '会谈情境：当事人说“他们都这样”时询问“这里的他们具体指谁”。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"澄清"},{"key":"B","text":"重述"},{"key":"C","text":"开放式提问"},{"key":"D","text":"封闭式提问"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境体现“澄清”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b4710428-e359-5f07-964c-4651c1d1ca08'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'single', '咨询师向来访者说明：“今天我们谈到三个部分，我先整理一下，你听听是否准确。”这段说明主要对应哪一项技术或原则？', '[{"key":"A","text":"开放式提问"},{"key":"B","text":"总结"},{"key":"C","text":"封闭式提问"},{"key":"D","text":"最小鼓励"}]'::jsonb, '{"correct":"B"}'::jsonb, '这段面向来访者的说明对应“总结”，重点是能否以合作、易懂的方式解释技术意图。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('855b7860-27e9-5746-bedb-27fcee45b6ef'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'single', '围绕“结构化”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"会谈开始共同确定议程，偏离较远时温和提醒剩余时间。"},{"key":"B","text":"依据概念进行判断：通过说明时间、目标、步骤和角色，使会谈保持清晰边界与方向。"},{"key":"C","text":"向来访者说明：我们还有二十分钟，可以继续这个主题，也可以留出时间讨论下一步，你更希望怎样安排？"},{"key":"D","text":"把结构化变成僵化控制，不允许重要新内容出现。"}]'::jsonb, '{"correct":"D"}'::jsonb, '应避免：把结构化变成僵化控制，不允许重要新内容出现。。规范依据是：通过说明时间、目标、步骤和角色，使会谈保持清晰边界与方向。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d22b1816-fafc-54e9-a3d7-1a4feda73e5c'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'multi', '从技术操作是否规范的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"当事人说了长段经历后，咨询师抓住关键事件和意义重新表达。"},{"key":"B","text":"你愿意多说一些那段经历对你的影响吗？"},{"key":"C","text":"用大量封闭问题主导整场会谈，使叙述碎片化。"},{"key":"D","text":"频繁、机械回应，打断当事人的节奏。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“重述”的规范应用，B体现向来访者说明“开放式提问”时的合作性表达；C、D分别是“封闭式提问”和“最小鼓励”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9bb0df4d-d732-5654-aebb-33a1e15df022'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'multi', '从合作性和来访者体验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"核对时间、频率、风险和设置等必要事实。"},{"key":"B","text":"我在听，你可以按自己的节奏继续。"},{"key":"C","text":"把澄清变成质疑当事人的真实性。"},{"key":"D","text":"只罗列事件，不呈现主题；或总结后不给当事人回应机会。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“封闭式提问”的规范应用，B体现向来访者说明“最小鼓励”时的合作性表达；C、D分别是“澄清”和“总结”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('79737389-bc4f-5bbe-85bd-e22361ead84a'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'multi', '从技术时机、边界与效果检验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"当事人说“他们都这样”时询问“这里的他们具体指谁”。"},{"key":"B","text":"今天我们谈到三个部分，我先整理一下，你听听是否准确。"},{"key":"C","text":"把结构化变成僵化控制，不允许重要新内容出现。"},{"key":"D","text":"机械重复原话，或在重述中加入未经核对的解释。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“澄清”的规范应用，B体现向来访者说明“总结”时的合作性表达；C、D分别是“结构化”和“重述”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('5c50d721-7c80-595b-b71e-bae86a8e9f03'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'blank', '请依据本章学习主线补全工作流程：倾听关键内容 → ____ → 重述与澄清 → 必要时提问 → 阶段性总结 → 共同选择下一焦点。', NULL, '{"correct":["用鼓励保持叙述"]}'::jsonb, '本章流程中该环节是“用鼓励保持叙述”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('131d4893-9a53-5f99-a4ed-c9d2a4352b85'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'blank', '请依据本章学习主线补全工作流程：倾听关键内容 → 用鼓励保持叙述 → 重述与澄清 → ____ → 阶段性总结 → 共同选择下一焦点。', NULL, '{"correct":["必要时提问"]}'::jsonb, '本章流程中该环节是“必要时提问”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b64af66a-a302-553b-95af-defd9a185cb9'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'blank', '请依据本章学习主线补全工作流程：倾听关键内容 → 用鼓励保持叙述 → 重述与澄清 → 必要时提问 → 阶段性总结 → ____。', NULL, '{"correct":["共同选择下一焦点"]}'::jsonb, '本章流程中该环节是“共同选择下一焦点”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('0fbf14e1-d573-55e1-82d4-2e34d0affa1e'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'short', '简答题：探索内容的技术包含哪些主要技术或核心要点？请列举并说明这些内容如何共同服务本章目标。', NULL, '{"reference":"参考要点：\n1）主要技术或核心要点包括：重述、开放式提问、封闭式提问、最小鼓励、澄清、总结、结构化。\n2）本章目标：掌握重述、开放式提问、封闭式提问、鼓励、澄清、总结与结构化等内容探索技术。\n3）作答不能只罗列名称，还应依据“倾听关键内容 → 用鼓励保持叙述 → 重述与澄清 → 必要时提问 → 阶段性总结 → 共同选择下一焦点。”说明各项技术在工作流程中的位置、目的与衔接关系。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('82aece2e-b1de-51ba-852c-0dcaca345222'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'short', '简答题：说明“重述”与“最小鼓励”各自的含义，并指出在探索内容的技术中的应用要点。', NULL, '{"reference":"参考要点：\n1）重述：用更简洁的语言表达当事人刚才陈述的核心内容，以确认理解并促进继续探索。\n2）最小鼓励：用简短词语、声音、点头或停顿表达正在倾听，鼓励当事人继续。\n3）应用：当事人说了长段经历后，咨询师抓住关键事件和意义重新表达。\n4）应用：在当事人停顿但仍在思考时，用“嗯”“然后呢”保持空间。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('52656a1f-9291-51fb-b979-3bb81f40bbfd'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'short', '简答题：如果来访者询问“为什么要使用澄清和总结”，咨询师应如何用易懂、合作且不过度承诺的方式说明？', NULL, '{"reference":"参考要点：\n1）澄清：我想确认一下，你说的“受不了”具体是指哪一种感受或情况？\n2）总结：今天我们谈到三个部分，我先整理一下，你听听是否准确。\n3）说明技术目的和选择理由，并邀请来访者表达是否符合其需要。\n4）避免专业权威式断言，也不承诺技术一定产生某种结果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d38d0e10-67b9-52a2-b5a7-f64985b89e97'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'case', '案例题：当事人在十分钟内讲了家庭、工作和身体三个主题，内容跳跃。请组合至少四种内容探索技术，帮助其形成清晰焦点。', NULL, '{"reference":"参考要点：用最小鼓励完成当前叙述；重述主要内容；澄清关键指代和事实；总结三个主题及共同线索；用开放式提问了解最困扰部分；通过结构化说明时间并共同选择焦点；避免连续审问或咨询师单方面定题。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('38ac1e55-7355-5330-894d-98acf2a76210'::uuid, 'd714a1f3-7270-5ae0-a850-57355ea42068'::uuid, 'case', '案例题：咨询师在使用“结构化”时采用了以下做法：“把结构化变成僵化控制，不允许重要新内容出现。”请指出问题，改写为更规范的处理，并说明如何检查来访者的反应。', NULL, '{"reference":"参考要点：该做法把“结构化”使用成了常见误区。规范依据是：通过说明时间、目标、步骤和角色，使会谈保持清晰边界与方向。可改为：会谈开始共同确定议程，偏离较远时温和提醒剩余时间；向来访者说明时可表达为：“我们还有二十分钟，可以继续这个主题，也可以留出时间讨论下一步，你更希望怎样安排。”随后应邀请来访者反馈贴合度、情绪反应和是否愿意继续，并根据反馈调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('dcede15e-5815-5af6-babe-e6a3690f465c'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'single', '下列哪一概念最符合这一描述：“用语言表达咨询师从当事人叙述与非语言线索中理解到的核心情绪。”？', '[{"key":"A","text":"情感反映"},{"key":"B","text":"隐性情感"},{"key":"C","text":"混合情感"},{"key":"D","text":"情感强度"}]'::jsonb, '{"correct":"A"}'::jsonb, '该描述对应“情感反映”。应用提示：当事人微笑着讲失去时，试探回应“笑容背后似乎也有难过”。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('296c3865-515c-598a-8897-09098dd4a560'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'single', '下列哪一概念最符合这一描述：“当事人直接说出或清楚表现出来、较容易被识别的情绪。”？', '[{"key":"A","text":"混合情感"},{"key":"B","text":"显性情感"},{"key":"C","text":"情感强度"},{"key":"D","text":"情感深化"}]'::jsonb, '{"correct":"B"}'::jsonb, '该描述对应“显性情感”。应用提示：当事人说“我很生气”时先准确回应，再探索其意义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('272b051a-aae1-531b-a473-329b4c97f169'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'single', '会谈情境：用试探语气反映可能存在的羞耻或害怕，并允许否认。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"情感深化"},{"key":"B","text":"情感调节窗口"},{"key":"C","text":"隐性情感"},{"key":"D","text":"情感反映"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境体现“隐性情感”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('8172bb6a-980d-5c70-9da1-ad64ce24498a'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'single', '会谈情境：帮助当事人同时容纳对离开关系的轻松与悲伤。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"情感调节窗口"},{"key":"B","text":"情感反映"},{"key":"C","text":"显性情感"},{"key":"D","text":"混合情感"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境体现“混合情感”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
