insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('2c30c145-eac1-5399-823e-69262e0466a4'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'single', '会谈情境：询问0到10的强度，并区分烦躁、愤怒和暴怒。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"情感强度"},{"key":"B","text":"情感反映"},{"key":"C","text":"显性情感"},{"key":"D","text":"隐性情感"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境体现“情感强度”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
