insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('55a79159-122f-5515-8e09-5263a2d60f08'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'single', '咨询师向来访者说明：“我们可以稍微靠近这份愤怒下面的感受，但节奏由你决定。”这段说明主要对应哪一项技术或原则？', '[{"key":"A","text":"显性情感"},{"key":"B","text":"情感深化"},{"key":"C","text":"隐性情感"},{"key":"D","text":"混合情感"}]'::jsonb, '{"correct":"B"}'::jsonb, '这段面向来访者的说明对应“情感深化”，重点是能否以合作、易懂的方式解释技术意图。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('7fb02b3f-35c0-5553-8ea3-e747caaf72d4'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'single', '围绕“情感调节窗口”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"把强烈宣泄本身当作治疗目标，忽略安全与整合。"},{"key":"B","text":"出现明显失控或解离线索时先稳定、定向和放慢。"},{"key":"C","text":"依据概念进行判断：当事人能够保持连接、思考和体验而不过度淹没或麻木的可工作唤起范围。"},{"key":"D","text":"向来访者说明：如果现在太强烈，我们先让身体稳定下来，再决定是否继续。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：把强烈宣泄本身当作治疗目标，忽略安全与整合。。规范依据是：当事人能够保持连接、思考和体验而不过度淹没或麻木的可工作唤起范围。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('18bf6864-88ea-5795-8ec1-3927ebdb62c0'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'multi', '从技术操作是否规范的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"当事人微笑着讲失去时，试探回应“笑容背后似乎也有难过”。"},{"key":"B","text":"你已经很清楚地感觉到生气，我们可以再看看这份生气指向什么。"},{"key":"C","text":"把推测当事实，以权威口吻揭示“真正情绪”。"},{"key":"D","text":"要求当事人选出唯一“真实”情绪。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“情感反映”的规范应用，B体现向来访者说明“显性情感”时的合作性表达；C、D分别是“隐性情感”和“混合情感”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('85162f81-bcad-55fc-b9ac-a41ff6f05615'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'multi', '从合作性和来访者体验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"用试探语气反映可能存在的羞耻或害怕，并允许否认。"},{"key":"B","text":"对同一件事同时轻松和难过并不矛盾，我们可以分别理解它们。"},{"key":"C","text":"使用过强情感词放大体验，或用过弱词淡化痛苦。"},{"key":"D","text":"越深越好，不顾当事人的准备和情绪承受窗口。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“隐性情感”的规范应用，B体现向来访者说明“混合情感”时的合作性表达；C、D分别是“情感强度”和“情感深化”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('e61ec4a9-84cf-567e-9c06-cd6d149d19d8'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'multi', '从技术时机、边界与效果检验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"询问0到10的强度，并区分烦躁、愤怒和暴怒。"},{"key":"B","text":"我们可以稍微靠近这份愤怒下面的感受，但节奏由你决定。"},{"key":"C","text":"把强烈宣泄本身当作治疗目标，忽略安全与整合。"},{"key":"D","text":"只重复事件内容，或把咨询师自己的情绪归给当事人。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“情感强度”的规范应用，B体现向来访者说明“情感深化”时的合作性表达；C、D分别是“情感调节窗口”和“情感反映”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('54d36644-bbef-59be-9660-83b41b56bd13'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'blank', '请依据本章学习主线补全工作流程：观察语言与非语言线索 → ____ → 核对准确性与强度 → 探索触发和意义 → 调节深度。', NULL, '{"correct":["提出试探性情感词"]}'::jsonb, '本章流程中该环节是“提出试探性情感词”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
