insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('23ffdf49-b84b-5622-85eb-2da03468d6f1'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'blank', '请依据本章学习主线补全工作流程：观察语言与非语言线索 → 提出试探性情感词 → 核对准确性与强度 → 探索触发和意义 → ____。', NULL, '{"correct":["调节深度"]}'::jsonb, '本章流程中该环节是“调节深度”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d76f43e3-e859-5b36-94d4-7ea5e14c5614'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'short', '简答题：探索情感的技术包含哪些主要技术或核心要点？请列举并说明这些内容如何共同服务本章目标。', NULL, '{"reference":"参考要点：\n1）主要技术或核心要点包括：情感反映、显性情感、隐性情感、混合情感、情感强度、情感深化、情感调节窗口。\n2）本章目标：识别显性与隐性情感，使用情感反映、情感澄清和适度深化，帮助当事人准确体验和表达情绪。\n3）作答不能只罗列名称，还应依据“观察语言与非语言线索 → 提出试探性情感词 → 核对准确性与强度 → 探索触发和意义 → 调节深度。”说明各项技术在工作流程中的位置、目的与衔接关系。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('fec7de5e-a136-5cbc-8b43-3155ae415f43'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'short', '简答题：说明“情感反映”与“混合情感”各自的含义，并指出在探索情感的技术中的应用要点。', NULL, '{"reference":"参考要点：\n1）情感反映：用语言表达咨询师从当事人叙述与非语言线索中理解到的核心情绪。\n2）混合情感：同一事件中同时存在方向不同或相互冲突的多种情绪。\n3）应用：当事人微笑着讲失去时，试探回应“笑容背后似乎也有难过”。\n4）应用：帮助当事人同时容纳对离开关系的轻松与悲伤。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('0d379f65-d088-54eb-8708-80b11e9fdc1f'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'short', '简答题：如果来访者询问“为什么要使用情感强度和情感深化”，咨询师应如何用易懂、合作且不过度承诺的方式说明？', NULL, '{"reference":"参考要点：\n1）情感强度：如果0代表没有、10代表最强，现在大约是多少？\n2）情感深化：我们可以稍微靠近这份愤怒下面的感受，但节奏由你决定。\n3）说明技术目的和选择理由，并邀请来访者表达是否符合其需要。\n4）避免专业权威式断言，也不承诺技术一定产生某种结果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f417c661-e1a2-5b39-ac4b-502031cf25e1'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'case', '案例题：当事人笑着说“没什么，只是父亲去世后我终于自由了”，随后沉默并握紧双手。请说明咨询师如何使用情感探索技术。', NULL, '{"reference":"参考要点：观察语言与非语言不一致；先用试探性的情感反映；允许混合情感并核对强度；探索自由、悲伤、内疚或害怕等可能意义；留意调节窗口，必要时稳定和放慢；不武断揭示、不强迫哭泣或宣泄。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1b9847bb-8545-5dd7-99be-226afad3737b'::uuid, '8de60b94-302a-5378-9b52-4e4c007ee39a'::uuid, 'case', '案例题：咨询师在使用“情感调节窗口”时采用了以下做法：“把强烈宣泄本身当作治疗目标，忽略安全与整合。”请指出问题，改写为更规范的处理，并说明如何检查来访者的反应。', NULL, '{"reference":"参考要点：该做法把“情感调节窗口”使用成了常见误区。规范依据是：当事人能够保持连接、思考和体验而不过度淹没或麻木的可工作唤起范围。可改为：出现明显失控或解离线索时先稳定、定向和放慢；向来访者说明时可表达为：“如果现在太强烈，我们先让身体稳定下来，再决定是否继续。”随后应邀请来访者反馈贴合度、情绪反应和是否愿意继续，并根据反馈调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c2aa4b52-5a9f-588c-a378-f85b761083a8'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'single', '下列哪一概念最符合这一描述：“把注意力从宽泛叙述引向某个关键体验、关系或当下反应，以便深入工作。”？', '[{"key":"A","text":"聚焦"},{"key":"B","text":"即时性"},{"key":"C","text":"自我表露"},{"key":"D","text":"过程观察"}]'::jsonb, '{"correct":"A"}'::jsonb, '该描述对应“聚焦”。应用提示：从多个事件中选择反复出现的“怕让人失望”继续探索。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('be40af43-9745-516c-b7b0-87e65aeec889'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'single', '下列哪一概念最符合这一描述：“有目的地保留语言空间，让当事人感受、思考或组织表达。”？', '[{"key":"A","text":"自我表露"},{"key":"B","text":"治疗性沉默"},{"key":"C","text":"过程观察"},{"key":"D","text":"高级共情"}]'::jsonb, '{"correct":"B"}'::jsonb, '该描述对应“治疗性沉默”。应用提示：当事人触及重要情绪后保持在场，不急于填满停顿。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('6d31df1d-1d7b-57c0-8ff6-177cba786874'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'single', '会谈情境：当事人担心咨询师失望时，邀请讨论此刻如何看待咨询师。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"高级共情"},{"key":"B","text":"阻抗探索"},{"key":"C","text":"即时性"},{"key":"D","text":"聚焦"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境体现“即时性”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b908174f-d0bb-5386-ac9e-7e7e9b9c4ff7'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'single', '会谈情境：短暂表达对当事人努力的真实触动，然后迅速回到当事人。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"阻抗探索"},{"key":"B","text":"聚焦"},{"key":"C","text":"治疗性沉默"},{"key":"D","text":"自我表露"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境体现“自我表露”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('14a96f01-7686-5ca9-9786-1c02280e1837'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'single', '会谈情境：指出每当谈到需要时当事人就转向玩笑，并询问其体验。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"过程观察"},{"key":"B","text":"聚焦"},{"key":"C","text":"治疗性沉默"},{"key":"D","text":"即时性"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境体现“过程观察”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
