insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('947922c9-a0be-51f8-9b5f-4f550021e7a1'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'single', '咨询师向来访者说明：“我有一个不确定的理解：你似乎既渴望靠近，又担心靠近后被拒绝，是这样吗？”这段说明主要对应哪一项技术或原则？', '[{"key":"A","text":"治疗性沉默"},{"key":"B","text":"高级共情"},{"key":"C","text":"即时性"},{"key":"D","text":"自我表露"}]'::jsonb, '{"correct":"B"}'::jsonb, '这段面向来访者的说明对应“高级共情”，重点是能否以合作、易懂的方式解释技术意图。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9f12fc82-98ed-53a7-88ee-1b6c257e0c55'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'single', '围绕“阻抗探索”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"好奇地询问任务没有完成的困难、担忧和意义。"},{"key":"B","text":"给当事人贴“不配合”标签或用权力迫使服从。"},{"key":"C","text":"依据概念进行判断：把回避、迟到、沉默或任务未完成视为需要理解的保护和沟通信号，而非单纯不合作。"},{"key":"D","text":"向来访者说明：没有完成可能在告诉我们这个任务不合适或太难，我们一起看看发生了什么。"}]'::jsonb, '{"correct":"B"}'::jsonb, '应避免：给当事人贴“不配合”标签或用权力迫使服从。。规范依据是：把回避、迟到、沉默或任务未完成视为需要理解的保护和沟通信号，而非单纯不合作。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('360a18af-aa9e-59ff-9212-e9bb4afb3692'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'multi', '从技术操作是否规范的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"从多个事件中选择反复出现的“怕让人失望”继续探索。"},{"key":"B","text":"我们可以安静一会儿，不必急着说；我会留在这里。"},{"key":"C","text":"把咨询师的不满直接宣泄给当事人。"},{"key":"D","text":"为了拉近关系大量讲自己，要求当事人照顾咨询师感受。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“聚焦”的规范应用，B体现向来访者说明“治疗性沉默”时的合作性表达；C、D分别是“即时性”和“自我表露”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('0762c042-e650-5ea0-bc1d-9f06a4bc6bf7'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'multi', '从合作性和来访者体验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"当事人担心咨询师失望时，邀请讨论此刻如何看待咨询师。"},{"key":"B","text":"听到你仍愿意尝试，我感到很受触动；这句话对你有什么影响？"},{"key":"C","text":"把观察包装成诊断或指责。"},{"key":"D","text":"脱离证据进行深层解读，并要求当事人接受。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“即时性”的规范应用，B体现向来访者说明“自我表露”时的合作性表达；C、D分别是“过程观察”和“高级共情”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('98d47efe-7a01-5066-921e-6890e27a92fe'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'multi', '从技术时机、边界与效果检验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"指出每当谈到需要时当事人就转向玩笑，并询问其体验。"},{"key":"B","text":"我有一个不确定的理解：你似乎既渴望靠近，又担心靠近后被拒绝，是这样吗？"},{"key":"C","text":"给当事人贴“不配合”标签或用权力迫使服从。"},{"key":"D","text":"由咨询师凭兴趣选题，忽略当事人目标。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“过程观察”的规范应用，B体现向来访者说明“高级共情”时的合作性表达；C、D分别是“阻抗探索”和“聚焦”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('bea7ab89-452a-5533-9372-e38ef8f066c7'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'blank', '请依据本章学习主线补全工作流程：确认联盟和节奏 → ____ → 使用拓展技术 → 观察当事人反应 → 回到当事人体验并共同修正。', NULL, '{"correct":["选择需要深化的线索"]}'::jsonb, '本章流程中该环节是“选择需要深化的线索”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
