insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('2492a049-d8f9-5b28-b910-5e85024813f2'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'blank', '请依据本章学习主线补全工作流程：确认联盟和节奏 → 选择需要深化的线索 → 使用拓展技术 → 观察当事人反应 → ____。', NULL, '{"correct":["回到当事人体验并共同修正"]}'::jsonb, '本章流程中该环节是“回到当事人体验并共同修正”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9efcb1f3-ec90-549c-8037-10f6cb90880d'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'short', '简答题：探索的拓展技术包含哪些主要技术或核心要点？请列举并说明这些内容如何共同服务本章目标。', NULL, '{"reference":"参考要点：\n1）主要技术或核心要点包括：聚焦、治疗性沉默、即时性、自我表露、过程观察、高级共情、阻抗探索。\n2）本章目标：在基础探索之上使用聚焦、沉默、即时性、适度自我表露、过程观察和高级共情，扩展当事人的觉察。\n3）作答不能只罗列名称，还应依据“确认联盟和节奏 → 选择需要深化的线索 → 使用拓展技术 → 观察当事人反应 → 回到当事人体验并共同修正。”说明各项技术在工作流程中的位置、目的与衔接关系。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('63187882-bcba-57ca-84e4-ea744dd97b6d'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'short', '简答题：说明“聚焦”与“自我表露”各自的含义，并指出在探索的拓展技术中的应用要点。', NULL, '{"reference":"参考要点：\n1）聚焦：把注意力从宽泛叙述引向某个关键体验、关系或当下反应，以便深入工作。\n2）自我表露：咨询师有选择地分享与当事人目标相关、负担较小且能促进工作的个人反应或经验。\n3）应用：从多个事件中选择反复出现的“怕让人失望”继续探索。\n4）应用：短暂表达对当事人努力的真实触动，然后迅速回到当事人。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('38e3e86d-f807-5585-bbcb-9c04240de993'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'short', '简答题：如果来访者询问“为什么要使用过程观察和高级共情”，咨询师应如何用易懂、合作且不过度承诺的方式说明？', NULL, '{"reference":"参考要点：\n1）过程观察：我注意到谈到需要帮助时你会笑着转开，这个观察对你有意义吗？\n2）高级共情：我有一个不确定的理解：你似乎既渴望靠近，又担心靠近后被拒绝，是这样吗？\n3）说明技术目的和选择理由，并邀请来访者表达是否符合其需要。\n4）避免专业权威式断言，也不承诺技术一定产生某种结果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('03b42bf2-fa1c-5c90-9ca5-4983b6f7d894'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'case', '案例题：当事人每次谈到亲密关系就开玩笑并快速换话题，本次又说“没什么可谈的”。请选择并组合拓展探索技术。', NULL, '{"reference":"参考要点：先保持共情与安全；用过程观察描述开玩笑和转题；以聚焦邀请停留；可使用短暂沉默；以高级共情提出“靠近与被拒绝”的试探假设；必要时使用即时性探索此刻关系；把回避理解为保护，不指责。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('e807244a-8b37-5247-bbae-c521b0d71bab'::uuid, '135122a0-78e5-5789-b229-bc96a7904079'::uuid, 'case', '案例题：咨询师在使用“阻抗探索”时采用了以下做法：“给当事人贴“不配合”标签或用权力迫使服从。”请指出问题，改写为更规范的处理，并说明如何检查来访者的反应。', NULL, '{"reference":"参考要点：该做法把“阻抗探索”使用成了常见误区。规范依据是：把回避、迟到、沉默或任务未完成视为需要理解的保护和沟通信号，而非单纯不合作。可改为：好奇地询问任务没有完成的困难、担忧和意义；向来访者说明时可表达为：“没有完成可能在告诉我们这个任务不合适或太难，我们一起看看发生了什么。”随后应邀请来访者反馈贴合度、情绪反应和是否愿意继续，并根据反馈调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c61500fc-1121-5b20-a845-d5c183e65ff7'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'single', '下列哪一概念最符合这一描述：“在探索基础上帮助当事人形成新的理解、发现模式和意义，并为行动建立方向的阶段。”？', '[{"key":"A","text":"领悟阶段"},{"key":"B","text":"新视角"},{"key":"C","text":"领悟假设"},{"key":"D","text":"协同建构"}]'::jsonb, '{"correct":"A"}'::jsonb, '该描述对应“领悟阶段”。应用提示：把不同关系中的相似反应联系起来，讨论其功能与代价。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('afca7034-cab2-5d98-813d-d2d7a17a62e3'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'single', '下列哪一概念最符合这一描述：“识别想法、情感、行为和关系反应在不同情境中的重复结构。”？', '[{"key":"A","text":"领悟假设"},{"key":"B","text":"模式识别"},{"key":"C","text":"协同建构"},{"key":"D","text":"领悟时机"}]'::jsonb, '{"correct":"B"}'::jsonb, '该描述对应“模式识别”。应用提示：发现当事人在工作和亲密关系中都通过先退出避免被拒绝。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a11561f4-f5e5-5341-9cf6-31fa785715b0'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'single', '会谈情境：从“我太脆弱”转向“回避曾保护我，但现在限制了连接”。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"领悟时机"},{"key":"B","text":"领悟的行动指向"},{"key":"C","text":"新视角"},{"key":"D","text":"领悟阶段"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境体现“新视角”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
