insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('51b6496c-5afa-52f5-986b-470d3567651b'::uuid, '325237dd-a658-54e8-8021-7686d933fcde'::uuid, 'single', '会谈情境：使用“我有一个猜想”并询问符合程度和例外。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"领悟的行动指向"},{"key":"B","text":"领悟阶段"},{"key":"C","text":"模式识别"},{"key":"D","text":"领悟假设"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境体现“领悟假设”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
