insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('7c734383-00d5-5fae-94c2-14dd67107767'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'short', '简答题：促进觉察的技术包含哪些主要技术或核心要点？请列举并说明这些内容如何共同服务本章目标。', NULL, '{"reference":"参考要点：\n1）主要技术或核心要点包括：挑战、不一致、支持性对质、信念检验、挑战时机、挑战后的反应、挑战与共情平衡。\n2）本章目标：使用挑战、对质和不一致识别等技术，帮助当事人觉察言行、目标与结果之间的差距，同时维持共情和联盟。\n3）作答不能只罗列名称，还应依据“确认关系基础 → 描述可观察的不一致 → 说明关切而非评判 → 邀请当事人反应 → 修复联盟并深化理解。”说明各项技术在工作流程中的位置、目的与衔接关系。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b3c7c89e-1786-5554-af4d-cb10e8958b82'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'short', '简答题：说明“挑战”与“信念检验”各自的含义，并指出在促进觉察的技术中的应用要点。', NULL, '{"reference":"参考要点：\n1）挑战：以尊重和合作方式指出限制性信念、回避或不一致，促进当事人检验原有模式。\n2）信念检验：通过证据、逻辑、结果和例外检验绝对化或限制性信念。\n3）应用：在充分共情后邀请当事人检查“必须让所有人满意”的现实性。\n4）应用：询问“所有人都必须满意”的证据、代价和例外。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('5bfc223c-f90e-536f-8b82-3f514f274b77'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'short', '简答题：如果来访者询问“为什么要使用挑战时机和挑战后的反应”，咨询师应如何用易懂、合作且不过度承诺的方式说明？', NULL, '{"reference":"参考要点：\n1）挑战时机：如果现在适合，我想指出一个可能有些不舒服的差异。\n2）挑战后的反应：刚才的话似乎让你退了一下，我想先了解它对你的影响。\n3）说明技术目的和选择理由，并邀请来访者表达是否符合其需要。\n4）避免专业权威式断言，也不承诺技术一定产生某种结果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b41601ce-04d5-5126-a94d-4b7c37e1b9a9'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'case', '案例题：当事人说最重要的目标是改善伴侣关系，却连续三周拒绝任何沟通尝试，并解释“真正爱我的人应该自动懂我”。请设计一次支持性挑战。', NULL, '{"reference":"参考要点：先共情其失望和被理解的需要；描述目标与行为的不一致；以合作方式检验“自动懂我”的信念；讨论该信念的证据、结果和例外；观察挑战后的羞耻或防御；邀请当事人形成自己的理解，不急于进入命令式行动。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('8438b2c7-aaaa-558d-b4b2-2266ab6d9a2b'::uuid, '6b37db4e-5fa9-5f22-80a3-3f496015842f'::uuid, 'case', '案例题：咨询师在使用“挑战与共情平衡”时采用了以下做法：“只共情不碰困难，或只挑战不承接体验。”请指出问题，改写为更规范的处理，并说明如何检查来访者的反应。', NULL, '{"reference":"参考要点：该做法把“挑战与共情平衡”使用成了常见误区。规范依据是：既保持对当事人经验的理解，也不回避指出阻碍目标的模式。可改为：用“既……又……”表达保护功能与改变代价；向来访者说明时可表达为：“我能理解你为什么这样保护自己，同时也想和你看看它现在带来的限制。”随后应邀请来访者反馈贴合度、情绪反应和是否愿意继续，并根据反馈调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a7648160-3027-517c-88f8-bf58c30ff343'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'single', '下列哪一概念最符合这一描述：“咨询师把分散材料连接成关于原因、功能、关系或模式的暂时性理解。”？', '[{"key":"A","text":"解释"},{"key":"B","text":"试探性语言"},{"key":"C","text":"解释证据"},{"key":"D","text":"功能性理解"}]'::jsonb, '{"correct":"A"}'::jsonb, '该描述对应“解释”。应用提示：连接早期被批评经验、当前完美要求和回避失败的模式。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('89d82968-0384-561d-8974-e0bfa92dd47b'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'single', '下列哪一概念最符合这一描述：“解释可以聚焦防御、关系模式、需要、冲突、认知或行为功能，应服务于当前目标。”？', '[{"key":"A","text":"解释证据"},{"key":"B","text":"解释焦点"},{"key":"C","text":"功能性理解"},{"key":"D","text":"解释深度"}]'::jsonb, '{"correct":"B"}'::jsonb, '该描述对应“解释焦点”。应用提示：围绕反复出现且与目标相关的回避功能进行解释。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('32511c9e-c854-5370-8d52-ae805bb6749e'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'single', '会谈情境：说“我有一个不确定的猜想，你听听看”。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"解释深度"},{"key":"B","text":"解释检验"},{"key":"C","text":"试探性语言"},{"key":"D","text":"解释"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境体现“试探性语言”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
