insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('aee92dc2-a45f-5da3-870a-590ee5e20279'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'single', '会谈情境：列出几个相关事件并邀请当事人补充或反驳。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"解释检验"},{"key":"B","text":"解释"},{"key":"C","text":"解释焦点"},{"key":"D","text":"解释证据"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境体现“解释证据”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
