insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('084714ef-f68f-5689-969e-bcc68c516262'::uuid, '3bdd5f85-322a-5f4a-9bc2-99893c1a2c33'::uuid, 'single', '会谈情境：理解讨好既减少冲突又损害真实表达。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"功能性理解"},{"key":"B","text":"解释"},{"key":"C","text":"解释焦点"},{"key":"D","text":"试探性语言"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境体现“功能性理解”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
