insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('704ec934-efee-594d-8472-bfd9ee475ae4'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'single', '会谈情境：不防御地了解批评中有效的信息和未满足需要。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"关系模式泛化"},{"key":"B","text":"治疗关系事件"},{"key":"C","text":"联盟破裂"},{"key":"D","text":"对抗型破裂"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境体现“对抗型破裂”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
