insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('8a7bc979-cc25-5702-8b3f-2252f9f75cb7'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'single', '会谈情境：咨询师承认推进过快并与当事人重新决定节奏。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"关系修复"},{"key":"B","text":"治疗关系事件"},{"key":"C","text":"联盟破裂"},{"key":"D","text":"撤退型破裂"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境体现“关系修复”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
