insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f4c692d3-0202-5301-8714-b5e1a2feeeea'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'single', '咨询师向来访者说明：“此刻你是否也担心我会像别人一样失望？我们可以一起看看。”这段说明主要对应哪一项技术或原则？', '[{"key":"A","text":"联盟破裂"},{"key":"B","text":"关系中的即时性"},{"key":"C","text":"撤退型破裂"},{"key":"D","text":"对抗型破裂"}]'::jsonb, '{"correct":"B"}'::jsonb, '这段面向来访者的说明对应“关系中的即时性”，重点是能否以合作、易懂的方式解释技术意图。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('8f18d580-41e0-5e5a-b86f-ff231314f4ca'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'single', '围绕“关系模式泛化”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"当事人在会谈中也先顺从后疏远时，连接其外部关系模式。"},{"key":"B","text":"认为咨询关系中的一切都能代表所有关系。"},{"key":"C","text":"依据概念进行判断：当咨询关系中的互动与当事人其他关系存在相似性时，作为假设共同检验。"},{"key":"D","text":"向来访者说明：这里的反应似乎和你描述的其他关系有一点相似，但需要由你判断。"}]'::jsonb, '{"correct":"B"}'::jsonb, '应避免：认为咨询关系中的一切都能代表所有关系。。规范依据是：当咨询关系中的互动与当事人其他关系存在相似性时，作为假设共同检验。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('61052353-8fc7-583a-bea8-25ba3b0a0ad2'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'multi', '从技术操作是否规范的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"当事人突然沉默后，咨询师停下来询问刚才发生了什么。"},{"key":"B","text":"如果我们的方向或方式不合适，我希望你能告诉我，我们可以一起调整。"},{"key":"C","text":"把安静和礼貌配合自动当成没有问题。"},{"key":"D","text":"与当事人争输赢或用专业权威压制不满。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“治疗关系事件”的规范应用，B体现向来访者说明“联盟破裂”时的合作性表达；C、D分别是“撤退型破裂”和“对抗型破裂”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1e230f0b-793b-57da-b8b5-8130cf44e40b'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'multi', '从合作性和来访者体验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"注意“都可以”背后的退缩并温和邀请真实意见。"},{"key":"B","text":"你对我刚才的方式很不满，我想先弄清楚哪里让你感到没有被理解。"},{"key":"C","text":"只解释当事人的模式而不承认咨询师贡献。"},{"key":"D","text":"把即时性变成咨询师个人需求的倾诉。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“撤退型破裂”的规范应用，B体现向来访者说明“对抗型破裂”时的合作性表达；C、D分别是“关系修复”和“关系中的即时性”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c63ad1ef-7141-5ba1-b088-4ea6b6c1eed9'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'multi', '从技术时机、边界与效果检验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"咨询师承认推进过快并与当事人重新决定节奏。"},{"key":"B","text":"此刻你是否也担心我会像别人一样失望？我们可以一起看看。"},{"key":"C","text":"认为咨询关系中的一切都能代表所有关系。"},{"key":"D","text":"只分析会谈外关系，忽略咨询室内正在发生的互动。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“关系修复”的规范应用，B体现向来访者说明“关系中的即时性”时的合作性表达；C、D分别是“关系模式泛化”和“治疗关系事件”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ed395b0a-bb59-571b-998d-cd33c22f17e6'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'blank', '请依据本章学习主线补全工作流程：识别关系事件 → ____ → 邀请双方视角 → 承担咨询师责任 → 理解关系模式 → 修复并形成新体验。', NULL, '{"correct":["描述当下互动"]}'::jsonb, '本章流程中该环节是“描述当下互动”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('0e205370-5e80-54bc-a62b-8a1cafd4dcb7'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'blank', '请依据本章学习主线补全工作流程：识别关系事件 → 描述当下互动 → 邀请双方视角 → ____ → 理解关系模式 → 修复并形成新体验。', NULL, '{"correct":["承担咨询师责任"]}'::jsonb, '本章流程中该环节是“承担咨询师责任”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f5187d04-1909-5347-bcf3-5e7ea17fa4da'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'blank', '请依据本章学习主线补全工作流程：识别关系事件 → 描述当下互动 → 邀请双方视角 → 承担咨询师责任 → 理解关系模式 → ____。', NULL, '{"correct":["修复并形成新体验"]}'::jsonb, '本章流程中该环节是“修复并形成新体验”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1d9fdfd5-ff42-5420-bab5-359ed6604eca'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'short', '简答题：处理治疗关系的技术包含哪些主要技术或核心要点？请列举并说明这些内容如何共同服务本章目标。', NULL, '{"reference":"参考要点：\n1）主要技术或核心要点包括：治疗关系事件、联盟破裂、撤退型破裂、对抗型破裂、关系修复、关系中的即时性、关系模式泛化。\n2）本章目标：把咨询关系中的重复模式、联盟破裂和咨询师反应转化为可讨论、可修复的治疗材料。\n3）作答不能只罗列名称，还应依据“识别关系事件 → 描述当下互动 → 邀请双方视角 → 承担咨询师责任 → 理解关系模式 → 修复并形成新体验。”说明各项技术在工作流程中的位置、目的与衔接关系。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b4ce92f0-c4c6-52f4-915e-3e0c8ce98679'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'short', '简答题：说明“治疗关系事件”与“对抗型破裂”各自的含义，并指出在处理治疗关系的技术中的应用要点。', NULL, '{"reference":"参考要点：\n1）治疗关系事件：会谈中影响信任、合作或情感联结的具体互动，包括靠近、撤退、误解和修复。\n2）对抗型破裂：当事人通过批评、拒绝、控制或直接表达不满呈现关系紧张。\n3）应用：当事人突然沉默后，咨询师停下来询问刚才发生了什么。\n4）应用：不防御地了解批评中有效的信息和未满足需要。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('73ba72db-3e2c-53f6-b409-cbf2836781ec'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'short', '简答题：如果来访者询问“为什么要使用关系修复和关系中的即时性”，咨询师应如何用易懂、合作且不过度承诺的方式说明？', NULL, '{"reference":"参考要点：\n1）关系修复：我刚才推进得太快，可能让你感到被逼迫；这是我需要调整的地方。\n2）关系中的即时性：此刻你是否也担心我会像别人一样失望？我们可以一起看看。\n3）说明技术目的和选择理由，并邀请来访者表达是否符合其需要。\n4）避免专业权威式断言，也不承诺技术一定产生某种结果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('10285d30-969e-5047-ad48-698512776b20'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'case', '案例题：当事人连续两次说“你和其他人一样根本不听我”，咨询师感到被误解并想解释自己。请说明如何处理这一关系事件。', NULL, '{"reference":"参考要点：暂停自我辩护；承认并邀请当事人描述具体体验；识别可能的对抗型破裂；检查咨询师是否推进、打断或误解；承担适当责任并修复；在安全后再试探连接其他关系模式；不把当事人的批评全部解释为投射。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c8d6a7f9-9248-5164-9588-b8a8f18c0aeb'::uuid, '42f37221-e8a0-59fe-acbc-485dae965be4'::uuid, 'case', '案例题：咨询师在使用“关系模式泛化”时采用了以下做法：“认为咨询关系中的一切都能代表所有关系。”请指出问题，改写为更规范的处理，并说明如何检查来访者的反应。', NULL, '{"reference":"参考要点：该做法把“关系模式泛化”使用成了常见误区。规范依据是：当咨询关系中的互动与当事人其他关系存在相似性时，作为假设共同检验。可改为：当事人在会谈中也先顺从后疏远时，连接其外部关系模式；向来访者说明时可表达为：“这里的反应似乎和你描述的其他关系有一点相似，但需要由你判断。”随后应邀请来访者反馈贴合度、情绪反应和是否愿意继续，并根据反馈调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('27e53a54-9162-523c-a6e8-14458b7644cf'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'single', '下列哪一概念最符合这一描述：“领悟阶段希望当事人形成的具体新理解，应与咨询目标和重复模式直接相关。”？', '[{"key":"A","text":"领悟目标"},{"key":"B","text":"由浅入深"},{"key":"C","text":"反应监测"},{"key":"D","text":"领悟巩固"}]'::jsonb, '{"correct":"A"}'::jsonb, '该描述对应“领悟目标”。应用提示：把目标表述为“理解为何一被批评就退出关系”。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('2c68a981-1547-54dc-8985-bda43bb11a33'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'single', '下列哪一概念最符合这一描述：“依据问题性质、联盟状态和当事人准备度选择挑战、解释或关系技术。”？', '[{"key":"A","text":"反应监测"},{"key":"B","text":"技术匹配"},{"key":"C","text":"领悟巩固"},{"key":"D","text":"替代性理解"}]'::jsonb, '{"correct":"B"}'::jsonb, '该描述对应“技术匹配”。应用提示：信念矛盾突出时挑战，材料分散时解释，关系紧张时先修复。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('42941dc8-6f67-5372-9dcb-452dca7ecee3'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'single', '会谈情境：先讨论当前循环，再连接早期关系经验。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"替代性理解"},{"key":"B","text":"向行动过渡"},{"key":"C","text":"由浅入深"},{"key":"D","text":"领悟目标"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境体现“由浅入深”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
