insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('09714f76-546f-5455-99c0-b80a5adfc718'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'single', '咨询师向来访者说明：“我们不是强迫你乐观，而是寻找更符合证据、也更有选择空间的理解。”这段说明主要对应哪一项技术或原则？', '[{"key":"A","text":"技术匹配"},{"key":"B","text":"替代性理解"},{"key":"C","text":"由浅入深"},{"key":"D","text":"反应监测"}]'::jsonb, '{"correct":"B"}'::jsonb, '这段面向来访者的说明对应“替代性理解”，重点是能否以合作、易懂的方式解释技术意图。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('2cb9a431-ed7c-5157-b075-378ffb109786'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'single', '围绕“向行动过渡”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"识别触发点后制定下次暂停旧反应的计划。"},{"key":"B","text":"依据概念进行判断：把领悟转化为具体可观察的改变目标、选择点和练习方向。"},{"key":"C","text":"在当事人尚未认同理解时立刻布置行动。"},{"key":"D","text":"向来访者说明：如果这个理解对你有用，我们再一起决定下一次可以尝试怎样不同。"}]'::jsonb, '{"correct":"C"}'::jsonb, '应避免：在当事人尚未认同理解时立刻布置行动。。规范依据是：把领悟转化为具体可观察的改变目标、选择点和练习方向。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d1420c1c-1eef-5da8-aee4-975bfe0de8a3'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'multi', '从技术操作是否规范的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"把目标表述为“理解为何一被批评就退出关系”。"},{"key":"B","text":"我会根据此刻最需要解决的是理解、矛盾还是关系来选择工作方式。"},{"key":"C","text":"一开始就给出深层人格或童年解释。"},{"key":"D","text":"只按预定计划推进，不理会当事人反应。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“领悟目标”的规范应用，B体现向来访者说明“技术匹配”时的合作性表达；C、D分别是“由浅入深”和“反应监测”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('3a98beec-46c9-5e3f-a6a0-73d5084ffa2f'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'multi', '从合作性和来访者体验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"先讨论当前循环，再连接早期关系经验。"},{"key":"B","text":"你的反应会告诉我们这个方向是否合适，我们可以随时调整。"},{"key":"C","text":"咨询师总结完就认为当事人已经掌握。"},{"key":"D","text":"用空泛积极口号覆盖真实困难。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“由浅入深”的规范应用，B体现向来访者说明“反应监测”时的合作性表达；C、D分别是“领悟巩固”和“替代性理解”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ece2dfb6-6f1c-5804-b579-3b77b5b0abad'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'multi', '从技术时机、边界与效果检验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"让当事人用自己的话总结模式并找出最近例子。"},{"key":"B","text":"我们不是强迫你乐观，而是寻找更符合证据、也更有选择空间的理解。"},{"key":"C","text":"在当事人尚未认同理解时立刻布置行动。"},{"key":"D","text":"追求宏大人格解释而缺少可工作的焦点。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“领悟巩固”的规范应用，B体现向来访者说明“替代性理解”时的合作性表达；C、D分别是“向行动过渡”和“领悟目标”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('fdb909b2-0245-55e4-866d-d45c414a384d'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'blank', '请依据本章学习主线补全工作流程：回顾探索材料 → ____ → 决定挑战/解释/关系工作 → 观察反应 → 调整深度 → 形成行动方向。', NULL, '{"correct":["选择领悟目标"]}'::jsonb, '本章流程中该环节是“选择领悟目标”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('85638e94-8566-53ff-ba21-8e46792d614c'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'blank', '请依据本章学习主线补全工作流程：回顾探索材料 → 选择领悟目标 → 决定挑战/解释/关系工作 → ____ → 调整深度 → 形成行动方向。', NULL, '{"correct":["观察反应"]}'::jsonb, '本章流程中该环节是“观察反应”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
