insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('6d25c74a-85a2-5349-a96b-ba672f08d18c'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'blank', '请依据本章学习主线补全工作流程：回顾探索材料 → 选择领悟目标 → 决定挑战/解释/关系工作 → 观察反应 → 调整深度 → ____。', NULL, '{"correct":["形成行动方向"]}'::jsonb, '本章流程中该环节是“形成行动方向”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('8aa05e2a-6ddb-579e-8a24-34099fd52049'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'short', '简答题：领悟阶段技术整合包含哪些主要技术或核心要点？请列举并说明这些内容如何共同服务本章目标。', NULL, '{"reference":"参考要点：\n1）主要技术或核心要点包括：领悟目标、技术匹配、由浅入深、反应监测、领悟巩固、替代性理解、向行动过渡。\n2）本章目标：整合挑战、解释和关系工作，根据当事人反应灵活选择技术，使新的理解既有深度又可被当事人使用。\n3）作答不能只罗列名称，还应依据“回顾探索材料 → 选择领悟目标 → 决定挑战/解释/关系工作 → 观察反应 → 调整深度 → 形成行动方向。”说明各项技术在工作流程中的位置、目的与衔接关系。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('dd7a801d-525e-52bd-80a4-62a3f04c2a5d'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'short', '简答题：说明“领悟目标”与“反应监测”各自的含义，并指出在领悟阶段技术整合中的应用要点。', NULL, '{"reference":"参考要点：\n1）领悟目标：领悟阶段希望当事人形成的具体新理解，应与咨询目标和重复模式直接相关。\n2）反应监测：持续观察当事人的认知、情绪、身体和关系反应，判断技术是否合适。\n3）应用：把目标表述为“理解为何一被批评就退出关系”。\n4）应用：当挑战后出现羞耻和撤退时立即放慢并修复。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('547946bd-db7f-5ea3-8a32-a5c95f709e24'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'short', '简答题：如果来访者询问“为什么要使用领悟巩固和替代性理解”，咨询师应如何用易懂、合作且不过度承诺的方式说明？', NULL, '{"reference":"参考要点：\n1）领悟巩固：你能否用自己的话说说今天形成的新理解，以及它在哪些场景出现？\n2）替代性理解：我们不是强迫你乐观，而是寻找更符合证据、也更有选择空间的理解。\n3）说明技术目的和选择理由，并邀请来访者表达是否符合其需要。\n4）避免专业权威式断言，也不承诺技术一定产生某种结果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('4a1cc616-2820-525d-8b17-94cfc5fb0ec4'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'case', '案例题：当事人已理解自己通过讨好避免冲突，但听到咨询师挑战后突然沉默并说“算了，我就是没用”。请说明领悟技术如何整合与调整。', NULL, '{"reference":"参考要点：暂停继续挑战并监测羞耻和联盟反应；共情并处理当下关系影响；澄清挑战是否被体验为批评；恢复安全后用较浅、试探性解释理解讨好的保护功能；让当事人用自己的话总结；得到认同后再形成行动方向。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('985004e0-cd63-5390-a264-9ed31a4c0330'::uuid, 'd07f5968-7a49-5fef-ba90-337d322d8dea'::uuid, 'case', '案例题：咨询师在使用“向行动过渡”时采用了以下做法：“在当事人尚未认同理解时立刻布置行动。”请指出问题，改写为更规范的处理，并说明如何检查来访者的反应。', NULL, '{"reference":"参考要点：该做法把“向行动过渡”使用成了常见误区。规范依据是：把领悟转化为具体可观察的改变目标、选择点和练习方向。可改为：识别触发点后制定下次暂停旧反应的计划；向来访者说明时可表达为：“如果这个理解对你有用，我们再一起决定下一次可以尝试怎样不同。”随后应邀请来访者反馈贴合度、情绪反应和是否愿意继续，并根据反馈调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('5d1393b6-bb2a-549b-a7b8-cd6f99902136'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'single', '下列哪一概念最符合这一描述：“把探索和领悟转化为新行为、技能、环境调整与持续练习的阶段。”？', '[{"key":"A","text":"行动阶段"},{"key":"B","text":"具体目标"},{"key":"C","text":"方案生成"},{"key":"D","text":"方案评估"}]'::jsonb, '{"correct":"A"}'::jsonb, '该描述对应“行动阶段”。应用提示：围绕已识别的回避模式设计一次可完成的沟通尝试。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('5fb2822f-5537-59be-8067-18b7a24119e5'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'single', '下列哪一概念最符合这一描述：“当事人对改变的意愿、信心、资源、风险和现实条件的综合状态。”？', '[{"key":"A","text":"方案生成"},{"key":"B","text":"行动准备度"},{"key":"C","text":"方案评估"},{"key":"D","text":"小步骤"}]'::jsonb, '{"correct":"B"}'::jsonb, '该描述对应“行动准备度”。应用提示：行动前询问重要性、信心和可能障碍。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('cf979dc2-933e-5354-a123-f22aeee7a966'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'single', '会谈情境：把“更自信”转为“本周会议至少表达一次不同意见”。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"小步骤"},{"key":"B","text":"行动反馈循环"},{"key":"C","text":"具体目标"},{"key":"D","text":"行动阶段"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境体现“具体目标”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
