insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('539981a2-547d-5328-86f6-401ba5844e30'::uuid, '962ae936-d2d2-54e1-bf67-94112a3402b4'::uuid, 'single', '会谈情境：对离职方案同时评估经济、健康、关系和替代选择。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"方案评估"},{"key":"B","text":"行动阶段"},{"key":"C","text":"行动准备度"},{"key":"D","text":"具体目标"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境体现“方案评估”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
