insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d6982629-72cc-5dff-8b8b-97567d087dbb'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'single', '咨询师向来访者说明：“我们把计划写成“如果……那么……”，让行动更容易启动。”这段说明主要对应哪一项技术或原则？', '[{"key":"A","text":"技能教学"},{"key":"B","text":"实施意图"},{"key":"C","text":"示范"},{"key":"D","text":"角色演练"}]'::jsonb, '{"correct":"B"}'::jsonb, '这段面向来访者的说明对应“实施意图”，重点是能否以合作、易懂的方式解释技术意图。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('2dde54c6-f91a-5621-a55a-1d5ef069f543'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'single', '围绕“障碍预演”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"把障碍理解为消极，不允许讨论失败可能。"},{"key":"B","text":"预演被拒绝、忘记或情绪升高时如何调整。"},{"key":"C","text":"依据概念进行判断：提前识别可能阻碍行动的情境、情绪和想法，并准备替代方案。"},{"key":"D","text":"向来访者说明：提前想到困难不是泼冷水，而是在为真实生活做准备。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：把障碍理解为消极，不允许讨论失败可能。。规范依据是：提前识别可能阻碍行动的情境、情绪和想法，并准备替代方案。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('800ec908-61cd-599e-a2c8-22c98f9964c1'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'multi', '从技术操作是否规范的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"将“少焦虑”改为“焦虑时完成三分钟呼吸并继续停留五分钟”。"},{"key":"B","text":"我会先说明这项技能为什么有用、怎样做，再由你判断是否适合。"},{"key":"C","text":"让当事人机械模仿咨询师风格。"},{"key":"D","text":"演练一次不顺就认定技能无效。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“行为目标化”的规范应用，B体现向来访者说明“技能教学”时的合作性表达；C、D分别是“示范”和“角色演练”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('747df7f9-946a-5197-83fa-a0df11260aeb'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'multi', '从合作性和来访者体验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"示范一次坚定而尊重的拒绝。"},{"key":"B","text":"我们先在这里试一遍，出错正好能帮助找到需要调整的地方。"},{"key":"C","text":"只说“很好”或全面批评人格。"},{"key":"D","text":"只靠意志和模糊提醒，不指定触发与行为。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“示范”的规范应用，B体现向来访者说明“角色演练”时的合作性表达；C、D分别是“行为反馈”和“实施意图”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('0e5c672a-a91d-5482-b67f-214b5107e6f6'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'multi', '从技术时机、边界与效果检验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"先指出清晰表达，再建议放慢语速和补充请求。"},{"key":"B","text":"我们把计划写成“如果……那么……”，让行动更容易启动。"},{"key":"C","text":"把障碍理解为消极，不允许讨论失败可能。"},{"key":"D","text":"只使用抽象感受词，无法判断进展。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“行为反馈”的规范应用，B体现向来访者说明“实施意图”时的合作性表达；C、D分别是“障碍预演”和“行为目标化”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('5468099f-2172-578e-a502-0ab7018af3c7'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'blank', '请依据本章学习主线补全工作流程：明确问题和目标 → ____ → 选择方案 → 教学与示范 → 演练反馈 → 制定实施计划 → 评估并巩固。', NULL, '{"correct":["生成方案"]}'::jsonb, '本章流程中该环节是“生成方案”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('65e5b4dc-f5b7-5a9d-8520-baf722e5af83'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'blank', '请依据本章学习主线补全工作流程：明确问题和目标 → 生成方案 → 选择方案 → ____ → 演练反馈 → 制定实施计划 → 评估并巩固。', NULL, '{"correct":["教学与示范"]}'::jsonb, '本章流程中该环节是“教学与示范”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('e9522e1a-b5b3-5e9a-8bfa-63a9abcc34a2'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'blank', '请依据本章学习主线补全工作流程：明确问题和目标 → 生成方案 → 选择方案 → 教学与示范 → 演练反馈 → ____ → 评估并巩固。', NULL, '{"correct":["制定实施计划"]}'::jsonb, '本章流程中该环节是“制定实施计划”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('3ab0a783-1201-5c26-b91c-39b525a00c4a'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'short', '简答题：完成行动任务的步骤包含哪些主要技术或核心要点？请列举并说明这些内容如何共同服务本章目标。', NULL, '{"reference":"参考要点：\n1）主要技术或核心要点包括：行为目标化、技能教学、示范、角色演练、行为反馈、实施意图、障碍预演。\n2）本章目标：掌握目标设定、方案探索、技能训练、实施计划、障碍处理和结果评估等完成行动任务的系统步骤。\n3）作答不能只罗列名称，还应依据“明确问题和目标 → 生成方案 → 选择方案 → 教学与示范 → 演练反馈 → 制定实施计划 → 评估并巩固。”说明各项技术在工作流程中的位置、目的与衔接关系。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('72c8b4cb-aa50-53f8-9e15-1937299fbd0d'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'short', '简答题：说明“行为目标化”与“角色演练”各自的含义，并指出在完成行动任务的步骤中的应用要点。', NULL, '{"reference":"参考要点：\n1）行为目标化：把改变愿望转化为具体情境中的可观察行为、频率和完成标准。\n2）角色演练：在安全环境中模拟真实情境，练习新技能并观察困难。\n3）应用：将“少焦虑”改为“焦虑时完成三分钟呼吸并继续停留五分钟”。\n4）应用：咨询师扮演上司，与当事人演练表达不同意见。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a2419a11-57cf-5327-b9d8-65dd0c3928aa'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'short', '简答题：如果来访者询问“为什么要使用行为反馈和实施意图”，咨询师应如何用易懂、合作且不过度承诺的方式说明？', NULL, '{"reference":"参考要点：\n1）行为反馈：我会具体说哪些行为有效、下一次可以调整什么。\n2）实施意图：我们把计划写成“如果……那么……”，让行动更容易启动。\n3）说明技术目的和选择理由，并邀请来访者表达是否符合其需要。\n4）避免专业权威式断言，也不承诺技术一定产生某种结果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('3638838c-4a28-5465-8333-d05e72938c4a'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'case', '案例题：当事人想在下周向上司提出工作边界，但过去一紧张就沉默。请按行动任务步骤设计会谈内训练和会谈外实施。', NULL, '{"reference":"参考要点：将目标具体化；说明表达边界技能；咨询师示范并让当事人角色演练；提供具体反馈并重复练习；设置“如果—那么”实施意图；预演上司拒绝和紧张升高；确定时间、支持与记录；下次根据结果调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('77354367-5349-5b3b-9e9b-7d6b53197bc9'::uuid, '9e643af4-10dd-5ef6-8d52-b0dcb3a76800'::uuid, 'case', '案例题：咨询师在使用“障碍预演”时采用了以下做法：“把障碍理解为消极，不允许讨论失败可能。”请指出问题，改写为更规范的处理，并说明如何检查来访者的反应。', NULL, '{"reference":"参考要点：该做法把“障碍预演”使用成了常见误区。规范依据是：提前识别可能阻碍行动的情境、情绪和想法，并准备替代方案。可改为：预演被拒绝、忘记或情绪升高时如何调整；向来访者说明时可表达为：“提前想到困难不是泼冷水，而是在为真实生活做准备。”随后应邀请来访者反馈贴合度、情绪反应和是否愿意继续，并根据反馈调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('fdbd2673-5f9f-55b7-b011-db8b0e83986a'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'single', '下列哪一概念最符合这一描述：“围绕同一行动目标组合多种互补技术，而不是堆叠无关方法。”？', '[{"key":"A","text":"技术整合"},{"key":"B","text":"家庭任务"},{"key":"C","text":"环境支持"},{"key":"D","text":"技能迁移"}]'::jsonb, '{"correct":"A"}'::jsonb, '该描述对应“技术整合”。应用提示：为表达边界组合教学、示范、演练和家庭任务。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f2652f42-38a2-5f46-a50a-9c97d9a8b58a'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'single', '下列哪一概念最符合这一描述：“在征得同意后提供基于目标的可选方案，并保留当事人的决定权。”？', '[{"key":"A","text":"环境支持"},{"key":"B","text":"合作式建议"},{"key":"C","text":"技能迁移"},{"key":"D","text":"行动复盘"}]'::jsonb, '{"correct":"B"}'::jsonb, '该描述对应“合作式建议”。应用提示：询问“你愿意听一个可能方案吗”，再讨论适配性。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('8d9db5cd-fdc3-5311-b922-d49295d97958'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'single', '会谈情境：任务难度、时间和记录方式由双方共同设定。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"行动复盘"},{"key":"B","text":"自主性保护"},{"key":"C","text":"家庭任务"},{"key":"D","text":"技术整合"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境体现“家庭任务”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
