insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f38de965-684e-527f-bc79-f04c67c674bd'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'single', '会谈情境：请可信任的人提醒，或提前准备书面要点。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"自主性保护"},{"key":"B","text":"技术整合"},{"key":"C","text":"合作式建议"},{"key":"D","text":"环境支持"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境体现“环境支持”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('aa8c458b-4992-5682-8534-9bae5c228109'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'single', '会谈情境：从咨询室演练迁移到朋友、同事和高难度关系。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"技能迁移"},{"key":"B","text":"技术整合"},{"key":"C","text":"合作式建议"},{"key":"D","text":"家庭任务"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境体现“技能迁移”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d212569c-80b0-5342-98b1-ca66f849f425'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'single', '咨询师向来访者说明：“我们不仅看有没有完成，还看发生了什么、学到了什么。”这段说明主要对应哪一项技术或原则？', '[{"key":"A","text":"合作式建议"},{"key":"B","text":"行动复盘"},{"key":"C","text":"家庭任务"},{"key":"D","text":"环境支持"}]'::jsonb, '{"correct":"B"}'::jsonb, '这段面向来访者的说明对应“行动复盘”，重点是能否以合作、易懂的方式解释技术意图。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b97b650a-558f-5417-b265-82ca5cf59f62'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'single', '围绕“自主性保护”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"当事人拒绝建议时探索原因并重新协商。"},{"key":"B","text":"把顺从当成进步，把不同意当成阻抗。"},{"key":"C","text":"依据概念进行判断：确保行动目标和选择属于当事人，咨询师提供结构与资源但不接管人生决定。"},{"key":"D","text":"向来访者说明：你有权决定是否做、做多少；我的角色是帮助你看清选择和后果。"}]'::jsonb, '{"correct":"B"}'::jsonb, '应避免：把顺从当成进步，把不同意当成阻抗。。规范依据是：确保行动目标和选择属于当事人，咨询师提供结构与资源但不接管人生决定。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1f71bf41-fafc-55b4-9e12-8a0f57db0b6b'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'multi', '从技术操作是否规范的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"为表达边界组合教学、示范、演练和家庭任务。"},{"key":"B","text":"我可以提供一个选项，你可以决定是否采用或怎样修改。"},{"key":"C","text":"布置与目标无关、难度过高的作业，未完成就批评。"},{"key":"D","text":"只要求当事人增强意志力，忽略环境限制。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“技术整合”的规范应用，B体现向来访者说明“合作式建议”时的合作性表达；C、D分别是“家庭任务”和“环境支持”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ecd8c72f-4780-518c-a894-a8f439d53306'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'multi', '从合作性和来访者体验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"任务难度、时间和记录方式由双方共同设定。"},{"key":"B","text":"改变不只靠意志，我们也可以调整环境，让新行为更容易发生。"},{"key":"C","text":"在一个情境成功就认为所有场景都会自动成功。"},{"key":"D","text":"复盘只问“做没做”，不分析过程。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“家庭任务”的规范应用，B体现向来访者说明“环境支持”时的合作性表达；C、D分别是“技能迁移”和“行动复盘”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('aa5498e2-4c1d-5bbb-98b2-7a55252a1514'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'multi', '从技术时机、边界与效果检验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"从咨询室演练迁移到朋友、同事和高难度关系。"},{"key":"B","text":"我们不仅看有没有完成，还看发生了什么、学到了什么。"},{"key":"C","text":"把顺从当成进步，把不同意当成阻抗。"},{"key":"D","text":"技术越多越好，忽略目标和学习负荷。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“技能迁移”的规范应用，B体现向来访者说明“行动复盘”时的合作性表达；C、D分别是“自主性保护”和“技术整合”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('12c712db-182c-5459-929f-02e521af5ba8'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'blank', '请依据本章学习主线补全工作流程：确认目标与自主性 → ____ → 会谈内学习演练 → 会谈外任务 → 结果反馈 → 调整并巩固。', NULL, '{"correct":["选择适合的行动技术"]}'::jsonb, '本章流程中该环节是“选择适合的行动技术”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('327c6d06-7cd6-5374-83be-0c28ce5fa7b3'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'blank', '请依据本章学习主线补全工作流程：确认目标与自主性 → 选择适合的行动技术 → 会谈内学习演练 → ____ → 结果反馈 → 调整并巩固。', NULL, '{"correct":["会谈外任务"]}'::jsonb, '本章流程中该环节是“会谈外任务”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('6c5c37df-38ca-5e1e-ba86-80e79ee1c5b8'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'blank', '请依据本章学习主线补全工作流程：确认目标与自主性 → 选择适合的行动技术 → 会谈内学习演练 → 会谈外任务 → 结果反馈 → ____。', NULL, '{"correct":["调整并巩固"]}'::jsonb, '本章流程中该环节是“调整并巩固”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('015c8df4-1a04-5495-aa01-5070f59589ef'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'short', '简答题：行动阶段技术整合包含哪些主要技术或核心要点？请列举并说明这些内容如何共同服务本章目标。', NULL, '{"reference":"参考要点：\n1）主要技术或核心要点包括：技术整合、合作式建议、家庭任务、环境支持、技能迁移、行动复盘、自主性保护。\n2）本章目标：整合教学、建议、示范、演练、反馈、家庭任务和环境支持，使行动既符合当事人自主性又具有可执行性。\n3）作答不能只罗列名称，还应依据“确认目标与自主性 → 选择适合的行动技术 → 会谈内学习演练 → 会谈外任务 → 结果反馈 → 调整并巩固。”说明各项技术在工作流程中的位置、目的与衔接关系。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c1050b76-7adc-5d64-9d44-de9eb3922ba0'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'short', '简答题：说明“技术整合”与“环境支持”各自的含义，并指出在行动阶段技术整合中的应用要点。', NULL, '{"reference":"参考要点：\n1）技术整合：围绕同一行动目标组合多种互补技术，而不是堆叠无关方法。\n2）环境支持：通过改变提示、资源、社会支持或情境安排提高行动成功率。\n3）应用：为表达边界组合教学、示范、演练和家庭任务。\n4）应用：请可信任的人提醒，或提前准备书面要点。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f6dd9472-6ece-51f5-8725-174ea7568313'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'short', '简答题：如果来访者询问“为什么要使用技能迁移和行动复盘”，咨询师应如何用易懂、合作且不过度承诺的方式说明？', NULL, '{"reference":"参考要点：\n1）技能迁移：我们会从较容易的场景开始，再逐步迁移到更困难的场景。\n2）行动复盘：我们不仅看有没有完成，还看发生了什么、学到了什么。\n3）说明技术目的和选择理由，并邀请来访者表达是否符合其需要。\n4）避免专业权威式断言，也不承诺技术一定产生某种结果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('358493b8-3747-5624-a513-94f10e2d9993'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'case', '案例题：当事人没有完成家庭任务，解释说任务像“咨询师布置的作业”，自己越想越抗拒。请用行动阶段整合原则处理。', NULL, '{"reference":"参考要点：不把未完成视为失败；探索任务是否缺乏自主性、难度过高或不符合价值；承认咨询师可能过度主导；重新确认目标；征得同意后共同生成方案；减小任务并增加环境支持；明确任务是实验并约定复盘。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('5ddb94b0-c02e-5402-a0c5-37bbddc8b02e'::uuid, 'dd81ba26-f021-5af8-98a6-d6edfadae2aa'::uuid, 'case', '案例题：咨询师在使用“自主性保护”时采用了以下做法：“把顺从当成进步，把不同意当成阻抗。”请指出问题，改写为更规范的处理，并说明如何检查来访者的反应。', NULL, '{"reference":"参考要点：该做法把“自主性保护”使用成了常见误区。规范依据是：确保行动目标和选择属于当事人，咨询师提供结构与资源但不接管人生决定。可改为：当事人拒绝建议时探索原因并重新协商；向来访者说明时可表达为：“你有权决定是否做、做多少；我的角色是帮助你看清选择和后果。”随后应邀请来访者反馈贴合度、情绪反应和是否愿意继续，并根据反馈调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('5c2ccd49-0460-5fc7-bece-18d74b36cc58'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'single', '下列哪一概念最符合这一描述：“整合问题、诱发因素、维持机制、资源、文化和目标形成可修正的工作假设。”？', '[{"key":"A","text":"个案概念化"},{"key":"B","text":"阶段往返"},{"key":"C","text":"技术意图"},{"key":"D","text":"当事人反应"}]'::jsonb, '{"correct":"A"}'::jsonb, '该描述对应“个案概念化”。应用提示：把症状、关系模式、优势和环境压力放入同一理解框架。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('62aca23b-d472-5ead-a8e3-992a82cd1971'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'single', '下列哪一概念最符合这一描述：“根据当事人的需要和会谈任务判断此刻更需要探索、领悟还是行动。”？', '[{"key":"A","text":"技术意图"},{"key":"B","text":"阶段判断"},{"key":"C","text":"当事人反应"},{"key":"D","text":"过程反馈"}]'::jsonb, '{"correct":"B"}'::jsonb, '该描述对应“阶段判断”。应用提示：情绪材料不清时回到探索，模式清楚后进入领悟，准备充分时行动。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ceea271c-5fe2-5c9a-bd52-f6dcce0602fd'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'single', '会谈情境：任务失败后回到探索障碍和理解模式。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"过程反馈"},{"key":"B","text":"整合一致性"},{"key":"C","text":"阶段往返"},{"key":"D","text":"个案概念化"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境体现“阶段往返”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('de6abc18-8f60-5cd3-a2fb-8a75fdb15c7d'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'single', '会谈情境：提问前判断是为澄清、深化还是满足自己的好奇。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"整合一致性"},{"key":"B","text":"个案概念化"},{"key":"C","text":"阶段判断"},{"key":"D","text":"技术意图"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境体现“技术意图”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('fc46adf0-3751-5ab6-b1c9-3ccc477d2346'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'single', '会谈情境：技术后出现开放、沉默或撤退时分别调整。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"当事人反应"},{"key":"B","text":"个案概念化"},{"key":"C","text":"阶段判断"},{"key":"D","text":"阶段往返"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境体现“当事人反应”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('bd157ec3-af3c-5da9-945e-b50a7ed76e37'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'single', '咨询师向来访者说明：“请告诉我今天哪部分有帮助、哪部分需要我做得不同。”这段说明主要对应哪一项技术或原则？', '[{"key":"A","text":"阶段判断"},{"key":"B","text":"过程反馈"},{"key":"C","text":"阶段往返"},{"key":"D","text":"技术意图"}]'::jsonb, '{"correct":"B"}'::jsonb, '这段面向来访者的说明对应“过程反馈”，重点是能否以合作、易懂的方式解释技术意图。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('efd754c3-5e8c-590f-8d75-15ac49a00a20'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'single', '围绕“整合一致性”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"所有阶段技术都指向减少回避并增加真实表达。"},{"key":"B","text":"依据概念进行判断：不同技术应围绕共同概念化、目标和关系逻辑协调使用。"},{"key":"C","text":"从不同流派随意拼接互相矛盾的做法。"},{"key":"D","text":"向来访者说明：我们使用的不同方法会围绕同一个目标，而不是彼此冲突。"}]'::jsonb, '{"correct":"C"}'::jsonb, '应避免：从不同流派随意拼接互相矛盾的做法。。规范依据是：不同技术应围绕共同概念化、目标和关系逻辑协调使用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('2f8c1f60-b7ce-5eb9-943d-9a41012c993e'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'multi', '从技术操作是否规范的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"把症状、关系模式、优势和环境压力放入同一理解框架。"},{"key":"B","text":"阶段不是固定课表，我们会根据此刻最需要的工作来选择。"},{"key":"C","text":"进入行动后就不能再讨论情绪或关系。"},{"key":"D","text":"只看技术形式，不考虑使用目的和影响。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“个案概念化”的规范应用，B体现向来访者说明“阶段判断”时的合作性表达；C、D分别是“阶段往返”和“技术意图”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9c061b53-131a-5d84-a5a1-1a224866c430'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'multi', '从合作性和来访者体验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"任务失败后回到探索障碍和理解模式。"},{"key":"B","text":"每一种提问和回应都应有清楚目的，并根据你的反应调整。"},{"key":"C","text":"只要技术理论正确就不需要观察反应。"},{"key":"D","text":"只在结束时进行满意度调查。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“阶段往返”的规范应用，B体现向来访者说明“技术意图”时的合作性表达；C、D分别是“当事人反应”和“过程反馈”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('51b06ce3-1dcb-5574-a5fb-e16fc018372a'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'multi', '从技术时机、边界与效果检验的角度看，下列哪些做法恰当？（多选）', '[{"key":"A","text":"技术后出现开放、沉默或撤退时分别调整。"},{"key":"B","text":"请告诉我今天哪部分有帮助、哪部分需要我做得不同。"},{"key":"C","text":"从不同流派随意拼接互相矛盾的做法。"},{"key":"D","text":"把概念化当作固定诊断标签或一次完成的结论。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A体现“当事人反应”的规范应用，B体现向来访者说明“过程反馈”时的合作性表达；C、D分别是“整合一致性”和“个案概念化”的常见误用。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('7a4d237b-29d1-566c-a034-e5abbe1d79e9'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'blank', '请依据本章学习主线补全工作流程：建立关系与评估 → ____ → 判断当前阶段任务 → 选择技术 → 监测反应与联盟 → 循环调整。', NULL, '{"correct":["形成初步概念化"]}'::jsonb, '本章流程中该环节是“形成初步概念化”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
