insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ee4fb8a0-5b12-5697-9e73-121426a27ef2'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'blank', '请依据本章学习主线补全工作流程：建立关系与评估 → 形成初步概念化 → 判断当前阶段任务 → ____ → 监测反应与联盟 → 循环调整。', NULL, '{"correct":["选择技术"]}'::jsonb, '本章流程中该环节是“选择技术”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
