insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f87c6c55-5976-5f0f-9752-63531cb38308'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'blank', '请依据本章学习主线补全工作流程：建立关系与评估 → 形成初步概念化 → 判断当前阶段任务 → 选择技术 → 监测反应与联盟 → ____。', NULL, '{"correct":["循环调整"]}'::jsonb, '本章流程中该环节是“循环调整”。流程题考查的是技术使用顺序与阶段任务，不是概念定义的重复记忆。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('cfacbf75-a8d8-5b2f-9601-5f4673708f88'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'short', '简答题：使用三阶段模型与当事人工作包含哪些主要技术或核心要点？请列举并说明这些内容如何共同服务本章目标。', NULL, '{"reference":"参考要点：\n1）主要技术或核心要点包括：个案概念化、阶段判断、阶段往返、技术意图、当事人反应、过程反馈、整合一致性。\n2）本章目标：在真实个案中灵活使用探索、领悟和行动，进行个案概念化、阶段判断、技术选择、反馈和过程调整。\n3）作答不能只罗列名称，还应依据“建立关系与评估 → 形成初步概念化 → 判断当前阶段任务 → 选择技术 → 监测反应与联盟 → 循环调整。”说明各项技术在工作流程中的位置、目的与衔接关系。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('86187e65-7c4b-5580-add3-5e1555ee89dd'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'short', '简答题：说明“个案概念化”与“技术意图”各自的含义，并指出在使用三阶段模型与当事人工作中的应用要点。', NULL, '{"reference":"参考要点：\n1）个案概念化：整合问题、诱发因素、维持机制、资源、文化和目标形成可修正的工作假设。\n2）技术意图：咨询师在使用技术前明确希望促进的过程目标，并检查是否服务当事人。\n3）应用：把症状、关系模式、优势和环境压力放入同一理解框架。\n4）应用：提问前判断是为澄清、深化还是满足自己的好奇。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ba98db8f-17ac-5049-b0d6-d0f0e8f7f6df'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'short', '简答题：如果来访者询问“为什么要使用当事人反应和过程反馈”，咨询师应如何用易懂、合作且不过度承诺的方式说明？', NULL, '{"reference":"参考要点：\n1）当事人反应：你的反应会告诉我们这个方式是否有帮助。\n2）过程反馈：请告诉我今天哪部分有帮助、哪部分需要我做得不同。\n3）说明技术目的和选择理由，并邀请来访者表达是否符合其需要。\n4）避免专业权威式断言，也不承诺技术一定产生某种结果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('4ece8ed5-a48b-53b2-9e68-985d40566803'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'case', '案例题：当事人在会谈中理解了回避模式并同意行动任务，但执行后焦虑显著升高并开始质疑咨询关系。请用三阶段模型重新安排工作。', NULL, '{"reference":"参考要点：暂停机械推进行动；评估风险和焦虑程度；回到探索行动后的体验和关系破裂；修复联盟；更新概念化，理解任务难度、信念和环境障碍；重新判断阶段；必要时缩小任务或先训练调节技能；持续使用过程反馈。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('3ed180b9-5cb3-59a0-bb46-aab8990bee95'::uuid, 'ee77c455-d350-5562-acc9-ab2af7253293'::uuid, 'case', '案例题：咨询师在使用“整合一致性”时采用了以下做法：“从不同流派随意拼接互相矛盾的做法。”请指出问题，改写为更规范的处理，并说明如何检查来访者的反应。', NULL, '{"reference":"参考要点：该做法把“整合一致性”使用成了常见误区。规范依据是：不同技术应围绕共同概念化、目标和关系逻辑协调使用。可改为：所有阶段技术都指向减少回避并增加真实表达；向来访者说明时可表达为：“我们使用的不同方法会围绕同一个目标，而不是彼此冲突。”随后应邀请来访者反馈贴合度、情绪反应和是否愿意继续，并根据反馈调整。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ecda23f0-2442-5ebc-ad8e-d6f7c00334fd'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'single', '下列哪一概念最符合这一描述：“根据目标进展、时间和服务设置提前协商结束，而非突然终止。”？', '[{"key":"A","text":"计划性结束"},{"key":"B","text":"回顾与巩固"},{"key":"C","text":"结束情感"},{"key":"D","text":"复发预防"}]'::jsonb, '{"correct":"A"}'::jsonb, '该描述对应“计划性结束”。应用提示：在剩余数次会谈时开始讨论结束日期和任务。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f0c515a8-7795-50bc-80de-a49a49531d4a'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'single', '下列哪一概念最符合这一描述：“综合目标完成、功能变化、剩余风险、资源和自主能力判断结束是否合适。”？', '[{"key":"A","text":"结束情感"},{"key":"B","text":"结束评估"},{"key":"C","text":"复发预防"},{"key":"D","text":"资源与转介"}]'::jsonb, '{"correct":"B"}'::jsonb, '该描述对应“结束评估”。应用提示：比较基线、目标进展和当事人自我评价。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('e3a83c97-1c6c-57f4-89b5-4b3c7656b2bb'::uuid, '20fff72e-5cff-597c-b56a-68dcbdf32126'::uuid, 'single', '会谈情境：让当事人列出最有用的方法和如何继续使用。这一处理最能体现下列哪一项技术或原则？', '[{"key":"A","text":"资源与转介"},{"key":"B","text":"非计划终止"},{"key":"C","text":"回顾与巩固"},{"key":"D","text":"计划性结束"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境体现“回顾与巩固”。判断依据是其操作目的与使用方式，而不是只记忆定义。')
