update public.chapter_review_notes set content = '# 【第十章 神经心理评估】
## 🎯 本章目标
理解脑—行为关系、神经心理评估目的、认知领域、测验组合、表现效度和综合解释。
## 🧭 学习主线
明确转介与病史 → 选择覆盖关键认知领域的工具 → 规范实施并观察 → 检查表现效度 → 比较个体内强弱与常模 → 结合医学教育情境解释 → 提出建议。
---PAGE---
# 【神经心理评估】
## 🧠 考试定义
通过病史、访谈、观察和标准化测验理解大脑功能与认知、情绪和行为表现关系的综合评估。
## 💬 如何向来访者解释
它综合多类信息了解不同认知功能及其对生活的影响。
## 🧩 应用情境
用于识别认知强弱、鉴别困难来源和制定干预。
## ⚠️ 易错点
神经心理评估只是做智力测验，或可以直接定位所有脑损伤。
---PAGE---
# 【认知领域】
## 🧠 考试定义
评估常涉及注意、记忆、语言、视空间、执行功能、加工速度和运动等相互关联的功能。
## 💬 如何向来访者解释
不同认知功能会相互影响，因此需要看整体模式。
## 🧩 应用情境
根据转介问题选择多个领域并比较模式。
## ⚠️ 易错点
某一测验只对应唯一脑区和唯一功能。
---PAGE---
# 【个体内差异】
## 🧠 考试定义
比较同一个体不同能力领域的相对强项与弱项，而不只看与常模的总体差距。
## 💬 如何向来访者解释
整体水平正常并不代表每个领域都没有明显强弱差异。
## 🧩 应用情境
平均总分下仍识别显著记忆弱项和视觉优势。
## ⚠️ 易错点
总分正常就说明所有功能正常。
---PAGE---
# 【表现效度】
## 🧠 考试定义
判断受评者是否提供了可解释的充分投入和一致表现，不等同于简单指控装病。
## 💬 如何向来访者解释
它判断当前结果是否可解释，原因可能包括多种状态，需要谨慎分析。
## 🧩 应用情境
结合专门指标、行为观察和情境解释低投入。
## ⚠️ 易错点
一次表现效度失败就证明故意欺骗。
---PAGE---
# 【病前功能估计】
## 🧠 考试定义
根据教育、职业、阅读等资料估计问题出现前的能力水平，为判断变化提供基线。
## 💬 如何向来访者解释
我们需要估计过去水平，才能判断现在是否真的下降。
## 🧩 应用情境
高教育者当前平均分可能仍代表明显下降。
## ⚠️ 易错点
直接用当前分数代表一生能力。
---PAGE---
# 【固定与灵活测验组合】
## 🧠 考试定义
固定组合便于全面和比较，灵活组合根据转介问题和发现调整，两者各有优缺点。
## 💬 如何向来访者解释
工具组合要回答问题，也要控制时间和疲劳。
## 🧩 应用情境
先覆盖核心领域，再根据异常追加测验。
## ⚠️ 易错点
测验越多越全面且没有疲劳成本。
---PAGE---
# 【脑行为推断】
## 🧠 考试定义
依据认知模式、病史、医学资料和功能表现形成关于机制的概率性解释。
## 💬 如何向来访者解释
一个分数不能单独确定脑区或原因，需要多项证据相互支持。
## 🧩 应用情境
把记忆、执行和情绪资料与病程共同分析。
## ⚠️ 易错点
单个低分可直接定位某脑区或病因。
---PAGE---
# 【功能建议】
## 🧠 考试定义
把评估发现转化为学习、工作、康复、环境调整和进一步检查的具体建议。
## 💬 如何向来访者解释
结果最终要帮助现实生活，因此建议会对应具体强弱和需求。
## 🧩 应用情境
根据加工速度弱项提供延长时间和分步指令。
## ⚠️ 易错点
建议与评估发现无关，或只罗列诊断名称。
---PAGE---
# 【本章整合】
## ✅ 作答检查
先判断当前阶段和任务，再选择概念或技术；说明使用理由、边界与下一步；涉及风险时优先安全、伦理和转介。
## 🧪 综合案例
高学历成年人主诉记忆下降，总分仍在平均范围，但与估计病前水平相比明显降低且执行功能也下降。请说明解释原则。
## 📌 参考思路
参考要点：不能仅凭常模平均排除下降；结合病前功能估计和个体内差异；检查表现效度、情绪、睡眠、药物和医学因素；观察记忆与执行模式；避免单一分数定位病因；与病史和功能变化整合，提出医学检查、补偿策略和随访建议。' where course_id = 'bff6d335-0102-5899-9dbc-f4b0c9eec8c5'::uuid and chapter_id = '3505ce48-30a4-59a4-8aaf-97b308ec5c5a'::uuid;
