insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a6346cdb-85ab-599e-a330-ae6ed02e84a9'::uuid, '91af23dc-ecce-5c52-800e-ad01af61572b'::uuid, 'single', '下列哪一概念最符合这一描述：“依据心理学理论和规则，对心理特质或行为进行定量描述的活动。”？', '[{"key":"A","text":"心理测量"},{"key":"B","text":"心理测验"},{"key":"C","text":"标准化"},{"key":"D","text":"常模参照"}]'::jsonb, '{"correct":"A"}'::jsonb, '正确概念是“心理测量”。需要量化焦虑程度并监测变化时选择合适的测量工具。')
