insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('e4fca5d4-7a68-555a-86ce-5b6e3df50fab'::uuid, '91af23dc-ecce-5c52-800e-ad01af61572b'::uuid, 'short', '简答题：说明“心理测量”与“心理测评”各自的含义，并指出在心理测量与评估基础中的应用要点。', NULL, '{"reference":"参考要点：\n1）心理测量：依据心理学理论和规则，对心理特质或行为进行定量描述的活动。\n2）心理测评：围绕评估问题整合访谈、观察、记录、量表和标准化测验等信息，形成判断和建议的过程。\n3）应用：需要量化焦虑程度并监测变化时选择合适的测量工具。\n4）应用：咨询初评中同时使用访谈、行为观察和量表，而不是只发问卷。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('0eccc4e5-fc4f-5f36-8262-039dd1e758f1'::uuid, '91af23dc-ecce-5c52-800e-ad01af61572b'::uuid, 'case', '案例题：一位咨询师只依据网络人格问卷的高分便告诉来访者“你一定有人格障碍”。请指出评估流程和伦理问题，并提出规范做法。', NULL, '{"reference":"参考要点：区分测验与完整测评；网络问卷的标准化、常模、信效度和适用范围需核查；量表不能单独诊断；应从转介问题出发，结合访谈、观察、历史和多源信息；说明局限并获得知情同意；超出胜任力时转介。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('7f9f8011-30a6-5998-8255-0cd442023b4c'::uuid, '0d255644-6228-51df-bb46-2b7483ae1652'::uuid, 'single', '下列哪一概念最符合这一描述：“认为观察分数由真分数与误差分数组成，即X=T+E。”？', '[{"key":"A","text":"经典测量理论"},{"key":"B","text":"信度"},{"key":"C","text":"重测信度"},{"key":"D","text":"内部一致性"}]'::jsonb, '{"correct":"A"}'::jsonb, '正确概念是“经典测量理论”。解释一次得分时同时考虑真实水平和测量误差。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('20b7cbf1-2bec-5225-8006-cccb0768acfc'::uuid, '0d255644-6228-51df-bb46-2b7483ae1652'::uuid, 'single', '下列哪一概念最符合这一描述：“使观察分数偏离目标真分数的随机或系统影响，来源可包括受评者、施测、环境和计分。”？', '[{"key":"A","text":"重测信度"},{"key":"B","text":"测量误差"},{"key":"C","text":"内部一致性"},{"key":"D","text":"评分者一致性"}]'::jsonb, '{"correct":"B"}'::jsonb, '正确概念是“测量误差”。睡眠不足、噪声和指导语变化都需记录并纳入解释。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('6f8a5732-2371-5a52-b804-b984822a1b19'::uuid, '0d255644-6228-51df-bb46-2b7483ae1652'::uuid, 'single', '下列哪一概念最符合这一描述：“测量结果的一致性、稳定性或精确程度，是分数可解释的必要条件。”？', '[{"key":"A","text":"内部一致性"},{"key":"B","text":"评分者一致性"},{"key":"C","text":"信度"},{"key":"D","text":"效度"}]'::jsonb, '{"correct":"C"}'::jsonb, '正确概念是“信度”。同一工具在相似条件下结果大幅波动时不能据此做重要决策。')
