insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('0d7903b6-e5d4-5c89-a7cc-95a74dadb3c6'::uuid, '0d255644-6228-51df-bb46-2b7483ae1652'::uuid, 'single', '应用情境：解释一次得分时同时考虑真实水平和测量误差。此时最需要优先依据哪一概念？', '[{"key":"A","text":"经典测量理论"},{"key":"B","text":"重测信度"},{"key":"C","text":"内部一致性"},{"key":"D","text":"评分者一致性"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境考查“经典测量理论”：认为观察分数由真分数与误差分数组成，即X=T+E。')
