insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('21735acf-b8f5-5d43-a397-99e0e196b619'::uuid, '0d255644-6228-51df-bb46-2b7483ae1652'::uuid, 'single', '应用情境：同一工具在相似条件下结果大幅波动时不能据此做重要决策。此时最需要优先依据哪一概念？', '[{"key":"A","text":"评分者一致性"},{"key":"B","text":"效度"},{"key":"C","text":"信度"},{"key":"D","text":"效度证据"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境考查“信度”：测量结果的一致性、稳定性或精确程度，是分数可解释的必要条件。')
