insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a45f5402-6f27-54e2-9b8a-5c879108697b'::uuid, '0d255644-6228-51df-bb46-2b7483ae1652'::uuid, 'single', '应用情境：评估相对稳定特质时查看适当时间间隔的重测证据。此时最需要优先依据哪一概念？', '[{"key":"A","text":"效度"},{"key":"B","text":"效度证据"},{"key":"C","text":"经典测量理论"},{"key":"D","text":"重测信度"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境考查“重测信度”：同一工具在两个时间点对同一群体施测所得分数的一致性。')
