insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('467c5aae-94b1-58f9-964b-0b896ef93869'::uuid, '0d255644-6228-51df-bb46-2b7483ae1652'::uuid, 'single', '应用情境：多条目单维量表可查看α或ω等内部一致性指标。此时最需要优先依据哪一概念？', '[{"key":"A","text":"内部一致性"},{"key":"B","text":"效度证据"},{"key":"C","text":"经典测量理论"},{"key":"D","text":"测量误差"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境考查“内部一致性”：测验内部条目在测量同一构念方面的一致程度。')
