insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('86679e2d-be60-5754-8e3a-cf017409ee7c'::uuid, '0d255644-6228-51df-bb46-2b7483ae1652'::uuid, 'single', '应用情境：行为编码或投射测验解释需要训练并报告评分者一致性。此时最需要优先依据哪一概念？', '[{"key":"A","text":"经典测量理论"},{"key":"B","text":"评分者一致性"},{"key":"C","text":"测量误差"},{"key":"D","text":"信度"}]'::jsonb, '{"correct":"B"}'::jsonb, '该情境考查“评分者一致性”：不同观察者或评分者对同一表现给出结果的一致程度。')
