insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('785c9035-3d8c-5da6-bf51-f6bba763a51d'::uuid, '0d255644-6228-51df-bb46-2b7483ae1652'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"经典测量理论：认为观察分数由真分数与误差分数组成，即X=T+E。"},{"key":"B","text":"测量误差：使观察分数偏离目标真分数的随机或系统影响，来源可包括受评者、施测、环境和计分。"},{"key":"C","text":"信度：信度高就说明一定测到了目标构念。"},{"key":"D","text":"重测信度：间隔越短或越长都必然越好，且任何构念都应高度稳定。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“经典测量理论”和“测量误差”。C、D是常见误区，不能作为规范理解或操作依据。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('7edc5853-15bb-5883-8aa5-386b1fb6777d'::uuid, '0d255644-6228-51df-bb46-2b7483ae1652'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"信度：测量结果的一致性、稳定性或精确程度，是分数可解释的必要条件。"},{"key":"B","text":"重测信度：同一工具在两个时间点对同一群体施测所得分数的一致性。"},{"key":"C","text":"内部一致性：指标越接近1越好，极高值不可能来自条目重复。"},{"key":"D","text":"评分者一致性：只要评分者有经验，就无需统一标准或检查一致性。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“信度”和“重测信度”。C、D是常见误区，不能作为规范理解或操作依据。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('4c497f17-937b-5db5-8dd6-a00ff6d19cd4'::uuid, '0d255644-6228-51df-bb46-2b7483ae1652'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"内部一致性：测验内部条目在测量同一构念方面的一致程度。"},{"key":"B","text":"评分者一致性：不同观察者或评分者对同一表现给出结果的一致程度。"},{"key":"C","text":"效度：效度是工具永久不变的单一属性，对所有群体用途都相同。"},{"key":"D","text":"效度证据：只要与另一个量表相关较高，就证明所有用途都有效。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“内部一致性”和“评分者一致性”。C、D是常见误区，不能作为规范理解或操作依据。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('5722b18f-2677-532c-bac3-d68fef32b808'::uuid, '0d255644-6228-51df-bb46-2b7483ae1652'::uuid, 'blank', '请填写概念：____是指认为观察分数由真分数与误差分数组成，即X=T+E。', NULL, '{"correct":["经典测量理论"]}'::jsonb, '答案是“经典测量理论”。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a1494506-3605-5181-bd8e-5d32e3718a62'::uuid, '0d255644-6228-51df-bb46-2b7483ae1652'::uuid, 'short', '简答题：说明“经典测量理论”与“测量误差”各自的含义，并指出在测量理论、信度与效度中的应用要点。', NULL, '{"reference":"参考要点：\n1）经典测量理论：认为观察分数由真分数与误差分数组成，即X=T+E。\n2）测量误差：使观察分数偏离目标真分数的随机或系统影响，来源可包括受评者、施测、环境和计分。\n3）应用：解释一次得分时同时考虑真实水平和测量误差。\n4）应用：睡眠不足、噪声和指导语变化都需记录并纳入解释。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9bbbb9b5-fc2b-503c-9408-d86f3f31f9e9'::uuid, '0d255644-6228-51df-bb46-2b7483ae1652'::uuid, 'case', '案例题：某焦虑量表三次结果分别为18、35和22，另一份名为“抑郁筛查”的问卷实际主要测社交回避。请分别分析信度和效度风险。', NULL, '{"reference":"参考要点：前者提示结果稳定性或施测条件存在问题，应检查时间间隔、状态、环境、计分及工具信度，不能贸然解释变化；后者属于分数解释与目标构念不匹配的效度风险，可能造成错误概念化；两者都需结合多源信息，不能单凭分数诊断。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('eede1d5f-6abb-575b-aed4-3e596828d6cd'::uuid, 'bf1d19d4-9fae-5256-9ef9-198755f5813a'::uuid, 'single', '下列哪一概念最符合这一描述：“用理论和操作语言明确要测量的心理概念、维度、边界及与相近概念的区别。”？', '[{"key":"A","text":"构念界定"},{"key":"B","text":"客位取向"},{"key":"C","text":"条目库"},{"key":"D","text":"内容效度"}]'::jsonb, '{"correct":"A"}'::jsonb, '正确概念是“构念界定”。开发孤独量表前区分孤独、社交隔离和社交焦虑。')
