insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('3d06032d-7178-5394-a900-822fe82ec71a'::uuid, 'bf1d19d4-9fae-5256-9ef9-198755f5813a'::uuid, 'single', '应用情境：邀请专家评审并用认知访谈检查受试者如何理解题目。此时最需要优先依据哪一概念？', '[{"key":"A","text":"内容效度"},{"key":"B","text":"工具选择"},{"key":"C","text":"构念界定"},{"key":"D","text":"主位取向"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境考查“内容效度”：专家和目标群体判断条目是否充分、适当地覆盖目标构念内容范围。')
