insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d46927cc-acd5-5647-bb51-4e5ab1247525'::uuid, 'bf1d19d4-9fae-5256-9ef9-198755f5813a'::uuid, 'single', '应用情境：删除无法区分高低水平或选项功能异常的条目。此时最需要优先依据哪一概念？', '[{"key":"A","text":"构念界定"},{"key":"B","text":"项目分析"},{"key":"C","text":"主位取向"},{"key":"D","text":"客位取向"}]'::jsonb, '{"correct":"B"}'::jsonb, '该情境考查“项目分析”：依据难度、区分度、条目—总分关系和选项表现等证据评价并筛选条目。')
