insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ae42778c-07ab-5fc7-84ff-815247858a6f'::uuid, 'bf1d19d4-9fae-5256-9ef9-198755f5813a'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"构念界定：用理论和操作语言明确要测量的心理概念、维度、边界及与相近概念的区别。"},{"key":"B","text":"主位取向：从本土文化和目标群体经验出发发展特有构念与条目的量表开发方式。"},{"key":"C","text":"客位取向：语言翻译准确就自动实现测量等效。"},{"key":"D","text":"条目库：每个维度只写一题，或大量使用双重问题和诱导语言。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“构念界定”和“主位取向”。C、D是常见误区，不能作为规范理解或操作依据。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('86af6136-d4b5-5efb-85c4-afe6d1ffb4f5'::uuid, 'bf1d19d4-9fae-5256-9ef9-198755f5813a'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"客位取向：检验外来构念和工具在新文化中的概念、测量与功能等效性并进行修订。"},{"key":"B","text":"条目库：围绕构念各维度建立数量充足、表述清晰且覆盖广泛的候选题目集合。"},{"key":"C","text":"内容效度：只由编制者本人觉得合理就足够。"},{"key":"D","text":"项目分析：只保留最容易题目就能提高量表质量。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“客位取向”和“条目库”。C、D是常见误区，不能作为规范理解或操作依据。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('46293d8c-6ca6-5cff-a3b3-e8464aff1996'::uuid, 'bf1d19d4-9fae-5256-9ef9-198755f5813a'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"内容效度：专家和目标群体判断条目是否充分、适当地覆盖目标构念内容范围。"},{"key":"B","text":"项目分析：依据难度、区分度、条目—总分关系和选项表现等证据评价并筛选条目。"},{"key":"C","text":"因素分析：因素分析可以自动证明构念的全部效度。"},{"key":"D","text":"工具选择：选择最流行、最熟悉或最短的量表即可。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“内容效度”和“项目分析”。C、D是常见误区，不能作为规范理解或操作依据。')
