insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('65f6ea8f-23cb-53c3-aaa3-2a013e7f944f'::uuid, '0dc5685e-7f84-53e3-839d-fab15368fdb1'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"初始评估：咨询开始阶段系统收集和整合信息，以理解问题、评估风险、确定目标与服务适配性的过程。"},{"key":"B","text":"转介问题：提出评估需求的核心问题，以及谁希望评估回答什么决策。"},{"key":"C","text":"呈现问题：只记录症状名称，不了解时间线和影响。"},{"key":"D","text":"心理社会历史：按清单机械盘问所有隐私，忽略评估问题。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“初始评估”和“转介问题”。C、D是常见误区，不能作为规范理解或操作依据。')
