insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f17e59de-90bf-5905-89d2-11e7552b99ab'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"量表融合：把量表作为访谈和观察的补充，用于筛查、量化、监测和提出进一步询问，而非取代临床判断。"},{"key":"B","text":"工具适配：确认量表的年龄、语言、用途、常模、信效度、施测方式和当前问题相匹配。"},{"key":"C","text":"施测前准备：边看说明书边施测，或不知道关键风险条目。"},{"key":"D","text":"计分质控：总分正确就不必检查单个条目和作答质量。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“量表融合”和“工具适配”。C、D是常见误区，不能作为规范理解或操作依据。')
