insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d127113d-ff31-503e-9dfe-a63834d93b45'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"施测前准备：熟悉指导语、计分、重点条目、材料设备和异常情况处理。"},{"key":"B","text":"计分质控：计分前检查漏答、无效反应和重点条目，再按规定转换和复核分数。"},{"key":"C","text":"分数解释：把百分位当正确率，或把界值当绝对诊断线。"},{"key":"D","text":"多源整合：选择最符合咨询师预期的一项信息，其余忽略。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“施测前准备”和“计分质控”。C、D是常见误区，不能作为规范理解或操作依据。')
