insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('40c35b20-7fd7-5bfe-ba9e-fba8374698bf'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"分数解释：结合原始分、标准分、百分位、界值、误差和常模条件说明结果意义。"},{"key":"B","text":"多源整合：比较访谈、观察、量表、记录和多信息提供者的一致与不一致，形成综合判断。"},{"key":"C","text":"初评报告：堆砌分数而不回答转介问题，或把推断写成事实。"},{"key":"D","text":"结果反馈：照读报告、使用大量术语或只讲缺陷。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“分数解释”和“多源整合”。C、D是常见误区，不能作为规范理解或操作依据。')
