insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('8612e7d2-3a20-523d-9671-a663d73b8c31'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'blank', '请填写概念：____是指把量表作为访谈和观察的补充，用于筛查、量化、监测和提出进一步询问，而非取代临床判断。', NULL, '{"correct":["量表融合"]}'::jsonb, '答案是“量表融合”。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('bf926aa1-35d2-5ada-ad0f-cf5056b1a288'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'short', '简答题：说明“量表融合”与“工具适配”各自的含义，并指出在初评量表、报告与结果反馈中的应用要点。', NULL, '{"reference":"参考要点：\n1）量表融合：把量表作为访谈和观察的补充，用于筛查、量化、监测和提出进一步询问，而非取代临床判断。\n2）工具适配：确认量表的年龄、语言、用途、常模、信效度、施测方式和当前问题相匹配。\n3）应用：抑郁量表高分后继续询问具体条目、功能和风险。\n4）应用：为青少年选择有对应年龄常模和使用证据的工具。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('7ca0b74a-51ff-5723-a083-9ca881c2cf9a'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'case', '案例题：初评中来访者抑郁量表总分中等，但自杀条目为3分；访谈时否认严重问题。请说明计分、询问、整合、报告和反馈步骤。', NULL, '{"reference":"参考要点：先检查作答完整性和计分；风险条目优先于总分，立即直接跟进想法、计划、意图、手段和保护因素；比较量表、访谈、行为观察及可能的最小化反应；必要时启动危机流程；报告区分数据与推断并说明局限；反馈使用清晰语言、回归安全和后续计划。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9fbea905-f351-568e-8f0f-e19e81712aa6'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '围绕“量表融合”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"只要总分超过界值就直接诊断。"},{"key":"B","text":"抑郁量表高分后继续询问具体条目、功能和风险。"},{"key":"C","text":"依据概念进行判断：把量表作为访谈和观察的补充，用于筛查、量化、监测和提出进一步询问，而非取代临床判断。"},{"key":"D","text":"向来访者说明：量表帮助我们发现需要进一步了解的方向，不会单独决定诊断。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：只要总分超过界值就直接诊断。。规范依据是：把量表作为访谈和观察的补充，用于筛查、量化、监测和提出进一步询问，而非取代临床判断。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a83aa6dd-8ae4-5dfb-9fe1-b83da35ca1a9'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '围绕“工具适配”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"为青少年选择有对应年龄常模和使用证据的工具。"},{"key":"B","text":"只因量表简短或免费就使用。"},{"key":"C","text":"依据概念进行判断：确认量表的年龄、语言、用途、常模、信效度、施测方式和当前问题相匹配。"},{"key":"D","text":"向来访者说明：我们会选择适合你的年龄和问题、且有研究依据的工具。"}]'::jsonb, '{"correct":"B"}'::jsonb, '应避免：只因量表简短或免费就使用。。规范依据是：确认量表的年龄、语言、用途、常模、信效度、施测方式和当前问题相匹配。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('dc1f3194-1356-53ad-835d-c5ef9aff8689'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '围绕“施测前准备”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"提前检查二维码、纸笔、年龄版本和计分规则。"},{"key":"B","text":"依据概念进行判断：熟悉指导语、计分、重点条目、材料设备和异常情况处理。"},{"key":"C","text":"边看说明书边施测，或不知道关键风险条目。"},{"key":"D","text":"向来访者说明：规范准备能减少流程差异，也避免遗漏重要信息。"}]'::jsonb, '{"correct":"C"}'::jsonb, '应避免：边看说明书边施测，或不知道关键风险条目。。规范依据是：熟悉指导语、计分、重点条目、材料设备和异常情况处理。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c4e66282-020b-5829-b300-c76c014bff4b'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '围绕“计分质控”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"发现风险条目非零时先跟进安全问题，而不是只算总分。"},{"key":"B","text":"依据概念进行判断：计分前检查漏答、无效反应和重点条目，再按规定转换和复核分数。"},{"key":"C","text":"向来访者说明：有些题目即使不影响总分，也可能提示需要立即进一步询问。"},{"key":"D","text":"总分正确就不必检查单个条目和作答质量。"}]'::jsonb, '{"correct":"D"}'::jsonb, '应避免：总分正确就不必检查单个条目和作答质量。。规范依据是：计分前检查漏答、无效反应和重点条目，再按规定转换和复核分数。')
