insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('56de4e5b-1407-57e0-945f-7d8c5f8318d1'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '围绕“分数解释”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"把百分位当正确率，或把界值当绝对诊断线。"},{"key":"B","text":"说明T分数位置、可信区间和常模适用范围。"},{"key":"C","text":"依据概念进行判断：结合原始分、标准分、百分位、界值、误差和常模条件说明结果意义。"},{"key":"D","text":"向来访者说明：分数表示相对位置和风险线索，不是对你的固定定义。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：把百分位当正确率，或把界值当绝对诊断线。。规范依据是：结合原始分、标准分、百分位、界值、误差和常模条件说明结果意义。')
