insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b2e18a83-08bd-58c7-9756-5ad449d4abba'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '围绕“多源整合”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"家长报告、儿童自述和学校观察不一致时分析情境差异。"},{"key":"B","text":"选择最符合咨询师预期的一项信息，其余忽略。"},{"key":"C","text":"依据概念进行判断：比较访谈、观察、量表、记录和多信息提供者的一致与不一致，形成综合判断。"},{"key":"D","text":"向来访者说明：不同来源不一致并不一定是谁错了，可能反映不同情境下的表现。"}]'::jsonb, '{"correct":"B"}'::jsonb, '应避免：选择最符合咨询师预期的一项信息，其余忽略。。规范依据是：比较访谈、观察、量表、记录和多信息提供者的一致与不一致，形成综合判断。')
