insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('2d787b94-9af5-53be-b7b5-af93c04b114c'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '下列哪一概念最符合这一描述：“关于自杀方法、时间、地点或步骤的具体构想，具体性和可行性会影响风险。”？', '[{"key":"A","text":"手段可及性"},{"key":"B","text":"自杀计划"},{"key":"C","text":"既往自杀行为"},{"key":"D","text":"危险与保护因素"}]'::jsonb, '{"correct":"B"}'::jsonb, '正确概念是“自杀计划”。询问是否想过怎么做、何时何地以及准备程度。')
