insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9513240e-ef17-5d9c-963b-8c12ea0624b2'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"自杀意念：关于死亡、自杀或不想活的想法，可从被动愿望到主动想法，需进一步评估。"},{"key":"B","text":"自杀计划：关于自杀方法、时间、地点或步骤的具体构想，具体性和可行性会影响风险。"},{"key":"C","text":"自杀意图：把计划和意图当作同一概念，或只凭口头否认排除意图。"},{"key":"D","text":"手段可及性：因询问手段具体而回避，或只建议“想开点”。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“自杀意念”和“自杀计划”。C、D是常见误区，不能作为规范理解或操作依据。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9fbfc18d-61a0-5aca-b4f2-7976c7ce0809'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"自杀意图：个体实施自杀行为的主观愿望、决心或预期死亡程度。"},{"key":"B","text":"手段可及性：个体能否获得计划所需工具、地点或条件，以及是否已做准备。"},{"key":"C","text":"既往自杀行为：久远行为与当前风险完全无关，或一次行为就决定终身高危。"},{"key":"D","text":"危险与保护因素：列出保护因素就能抵消明确计划和意图。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“自杀意图”和“手段可及性”。C、D是常见误区，不能作为规范理解或操作依据。')
