insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('3c549ff4-514a-55b7-9010-78620e568e68'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"既往自杀行为：既往尝试、预备行为、中止或被阻止的行为，是评估未来风险的重要信息。"},{"key":"B","text":"危险与保护因素：危险因素增加风险，保护因素提供连接、责任、价值、支持和求助可能，两者需动态整合。"},{"key":"C","text":"安全计划：让来访签“不自杀承诺”即可替代安全计划。"},{"key":"D","text":"紧急升级处置：为了保密绝不联系任何人，或任何意念都立即报警。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“既往自杀行为”和“危险与保护因素”。C、D是常见误区，不能作为规范理解或操作依据。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('7033da73-6ad9-5ce9-8a1d-93b2f2f5ade5'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'blank', '请填写概念：____是指关于死亡、自杀或不想活的想法，可从被动愿望到主动想法，需进一步评估。', NULL, '{"correct":["自杀意念"]}'::jsonb, '答案是“自杀意念”。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('bf0270dc-5c0d-5ee6-89e3-b76729f6de8e'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'short', '简答题：说明“自杀意念”与“自杀计划”各自的含义，并指出在危机与自杀风险评估中的应用要点。', NULL, '{"reference":"参考要点：\n1）自杀意念：关于死亡、自杀或不想活的想法，可从被动愿望到主动想法，需进一步评估。\n2）自杀计划：关于自杀方法、时间、地点或步骤的具体构想，具体性和可行性会影响风险。\n3）应用：来访说“睡着不醒就好了”时继续询问频率、可控性和是否出现主动想法。\n4）应用：询问是否想过怎么做、何时何地以及准备程度。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('441a5a2e-072e-5255-ae17-a1d8bde98157'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'case', '案例题：来访者说“不想活了”，承认今晚想服用家中大量药物，已把药放在床边，但又说不想让家人担心。请完成风险评估与处置。', NULL, '{"reference":"参考要点：直接评估意念、具体计划、今晚时间、意图、药物可及性、既往行为、物质使用、精神状态和保护因素；该情境存在迫近高风险，保护因素不能抵消；不让其独处或自行离开；限制手段并启动机构紧急流程，联系急救/急诊及必要支持者；说明保密例外；详细记录判断、咨询和处置。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('cd43a93d-1a39-5d9f-9896-cc6db17574c8'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '围绕“自杀意念”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"只有明确说“我要自杀”才算风险，或问自杀会诱发自杀。"},{"key":"B","text":"来访说“睡着不醒就好了”时继续询问频率、可控性和是否出现主动想法。"},{"key":"C","text":"依据概念进行判断：关于死亡、自杀或不想活的想法，可从被动愿望到主动想法，需进一步评估。"},{"key":"D","text":"向来访者说明：很多人在极度痛苦时会有类似想法，直接询问能帮助我们更安全地理解情况。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：只有明确说“我要自杀”才算风险，或问自杀会诱发自杀。。规范依据是：关于死亡、自杀或不想活的想法，可从被动愿望到主动想法，需进一步评估。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9728786a-cc66-5605-a1b0-3e6e41656819'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '围绕“自杀计划”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"询问是否想过怎么做、何时何地以及准备程度。"},{"key":"B","text":"有想法但没有计划就一定安全，或有计划就能单独决定风险等级。"},{"key":"C","text":"依据概念进行判断：关于自杀方法、时间、地点或步骤的具体构想，具体性和可行性会影响风险。"},{"key":"D","text":"向来访者说明：我需要了解想法是否已经变得具体，这有助于决定需要怎样的保护。"}]'::jsonb, '{"correct":"B"}'::jsonb, '应避免：有想法但没有计划就一定安全，或有计划就能单独决定风险等级。。规范依据是：关于自杀方法、时间、地点或步骤的具体构想，具体性和可行性会影响风险。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('12e201d9-3fb2-5bad-a812-c5c886ff142d'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '围绕“自杀意图”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"区分“想让痛苦停止”和“确实准备结束生命”的程度。"},{"key":"B","text":"依据概念进行判断：个体实施自杀行为的主观愿望、决心或预期死亡程度。"},{"key":"C","text":"把计划和意图当作同一概念，或只凭口头否认排除意图。"},{"key":"D","text":"向来访者说明：除了有没有方法，我们还要了解你有多可能真的去实施。"}]'::jsonb, '{"correct":"C"}'::jsonb, '应避免：把计划和意图当作同一概念，或只凭口头否认排除意图。。规范依据是：个体实施自杀行为的主观愿望、决心或预期死亡程度。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('acae9057-a39d-53e7-857e-c4d365b04ebe'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '围绕“手段可及性”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"询问药物、武器、高处或其他手段是否可获得，并推动安全限制。"},{"key":"B","text":"依据概念进行判断：个体能否获得计划所需工具、地点或条件，以及是否已做准备。"},{"key":"C","text":"向来访者说明：了解并暂时限制可用手段，是降低冲动时危险的重要步骤。"},{"key":"D","text":"因询问手段具体而回避，或只建议“想开点”。"}]'::jsonb, '{"correct":"D"}'::jsonb, '应避免：因询问手段具体而回避，或只建议“想开点”。。规范依据是：个体能否获得计划所需工具、地点或条件，以及是否已做准备。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('df893c3c-f2d6-5831-85cc-4b38228892bf'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '围绕“既往自杀行为”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"久远行为与当前风险完全无关，或一次行为就决定终身高危。"},{"key":"B","text":"询问次数、方法、医疗严重度、意图和当时后果。"},{"key":"C","text":"依据概念进行判断：既往尝试、预备行为、中止或被阻止的行为，是评估未来风险的重要信息。"},{"key":"D","text":"向来访者说明：过去发生过什么能帮助我们理解当前风险模式，但仍需结合现在情况。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：久远行为与当前风险完全无关，或一次行为就决定终身高危。。规范依据是：既往尝试、预备行为、中止或被阻止的行为，是评估未来风险的重要信息。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('5367bc29-32b9-5f36-931f-9cdc2693634c'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '围绕“危险与保护因素”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"同时评估物质使用、绝望、近期丧失以及家庭支持、求助意愿等。"},{"key":"B","text":"列出保护因素就能抵消明确计划和意图。"},{"key":"C","text":"依据概念进行判断：危险因素增加风险，保护因素提供连接、责任、价值、支持和求助可能，两者需动态整合。"},{"key":"D","text":"向来访者说明：支持和牵挂很重要，但在风险很高时仍需要更直接的安全措施。"}]'::jsonb, '{"correct":"B"}'::jsonb, '应避免：列出保护因素就能抵消明确计划和意图。。规范依据是：危险因素增加风险，保护因素提供连接、责任、价值、支持和求助可能，两者需动态整合。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('fe9f7fd8-c1a4-5701-baa9-eaab72ac35cb'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '下列哪一概念最符合这一描述：“相对稳定且有组织的心理特征与机制，影响个体与内部、物理和社会环境的交互与适应。”？', '[{"key":"A","text":"人格"},{"key":"B","text":"投射测验"},{"key":"C","text":"五因素模型"},{"key":"D","text":"作答风格"}]'::jsonb, '{"correct":"A"}'::jsonb, '正确概念是“人格”。解释人格时同时考虑稳定倾向和情境中的行为变化。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c9c60f7a-9d93-57ae-b223-5780d0e7cdeb'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '下列哪一概念最符合这一描述：“使用明确题目、固定反应和标准计分，通常具有常模和信效度证据的自陈或他评工具。”？', '[{"key":"A","text":"五因素模型"},{"key":"B","text":"结构型人格测验"},{"key":"C","text":"作答风格"},{"key":"D","text":"人格常模解释"}]'::jsonb, '{"correct":"B"}'::jsonb, '正确概念是“结构型人格测验”。用标准化人格量表比较特质并检查效度指标。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('234ba1da-1928-54b0-8e94-d947f00d04c4'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '下列哪一概念最符合这一描述：“使用相对模糊、非结构化刺激，引出个体的知觉、需要和主题，评分解释更依赖专业系统。”？', '[{"key":"A","text":"作答风格"},{"key":"B","text":"人格常模解释"},{"key":"C","text":"投射测验"},{"key":"D","text":"人格评估多方法"}]'::jsonb, '{"correct":"C"}'::jsonb, '正确概念是“投射测验”。使用规范评分体系并与其他资料结合。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('e7e7ef93-eac2-57f3-a4cf-468d1ba60c92'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '下列哪一概念最符合这一描述：“用开放性、尽责性、外向性、宜人性和神经质描述广泛人格特质维度。”？', '[{"key":"A","text":"人格常模解释"},{"key":"B","text":"人格评估多方法"},{"key":"C","text":"人格反馈"},{"key":"D","text":"五因素模型"}]'::jsonb, '{"correct":"D"}'::jsonb, '正确概念是“五因素模型”。用连续维度描述倾向，而不是贴好坏标签。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('87fa87db-1373-5e35-9ef3-1931ecd0912c'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '下列哪一概念最符合这一描述：“与目标特质无关但系统影响自陈结果的反应方式，如社会赞许、随机、极端或默认同意。”？', '[{"key":"A","text":"作答风格"},{"key":"B","text":"人格评估多方法"},{"key":"C","text":"人格反馈"},{"key":"D","text":"人格"}]'::jsonb, '{"correct":"A"}'::jsonb, '正确概念是“作答风格”。检查效度指标、作答时间和前后不一致。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d57a6709-a4d0-5abd-84f2-4c5e2b1b422a'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '下列哪一概念最符合这一描述：“将特质或临床量表分数与适配参照群体比较，并结合可信区间和基率解释。”？', '[{"key":"A","text":"人格反馈"},{"key":"B","text":"人格常模解释"},{"key":"C","text":"人格"},{"key":"D","text":"结构型人格测验"}]'::jsonb, '{"correct":"B"}'::jsonb, '正确概念是“人格常模解释”。说明高分是相对位置，不等于病理诊断。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('32369c5c-2d3b-5e2d-8144-69416a185a32'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '下列哪一概念最符合这一描述：“把自陈、访谈、观察、他评、历史与必要测验整合，以减少单一来源局限。”？', '[{"key":"A","text":"人格"},{"key":"B","text":"结构型人格测验"},{"key":"C","text":"人格评估多方法"},{"key":"D","text":"投射测验"}]'::jsonb, '{"correct":"C"}'::jsonb, '正确概念是“人格评估多方法”。比较本人和伴侣报告差异并分析情境。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('0f910a93-f3f6-51ba-b6f0-a6e452efe241'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '下列哪一概念最符合这一描述：“以描述性、非污名化和情境化方式反馈特质、优势、风险与改变空间。”？', '[{"key":"A","text":"结构型人格测验"},{"key":"B","text":"投射测验"},{"key":"C","text":"五因素模型"},{"key":"D","text":"人格反馈"}]'::jsonb, '{"correct":"D"}'::jsonb, '正确概念是“人格反馈”。说“压力下更倾向退缩”，而非“你就是回避型的人”。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('aefa5b08-0bf5-5638-adf4-6bb0f87df0c9'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '应用情境：解释人格时同时考虑稳定倾向和情境中的行为变化。此时最需要优先依据哪一概念？', '[{"key":"A","text":"人格"},{"key":"B","text":"五因素模型"},{"key":"C","text":"作答风格"},{"key":"D","text":"人格常模解释"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境考查“人格”：相对稳定且有组织的心理特征与机制，影响个体与内部、物理和社会环境的交互与适应。')
