insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1f7a03b1-34a1-5f9a-bf5a-bb2cf530c51a'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '应用情境：用标准化人格量表比较特质并检查效度指标。此时最需要优先依据哪一概念？', '[{"key":"A","text":"作答风格"},{"key":"B","text":"结构型人格测验"},{"key":"C","text":"人格常模解释"},{"key":"D","text":"人格评估多方法"}]'::jsonb, '{"correct":"B"}'::jsonb, '该情境考查“结构型人格测验”：使用明确题目、固定反应和标准计分，通常具有常模和信效度证据的自陈或他评工具。')
