insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('57dd620d-2899-50d8-a326-df5522f78b50'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '应用情境：用连续维度描述倾向，而不是贴好坏标签。此时最需要优先依据哪一概念？', '[{"key":"A","text":"人格评估多方法"},{"key":"B","text":"人格反馈"},{"key":"C","text":"人格"},{"key":"D","text":"五因素模型"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境考查“五因素模型”：用开放性、尽责性、外向性、宜人性和神经质描述广泛人格特质维度。')
