insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a3b282ab-f508-5b3c-bb03-56be4c04059b'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"临床量表：反映若干症状、人格和适应相关经验模式的标准化量表，需结合剖面解释。"},{"key":"B","text":"剖面解释：综合效度、整体形态、最高点、量表组合、基率和转介问题解释分数模式。"},{"key":"C","text":"人格病理：有某种特质或人际困难就等于人格障碍。"},{"key":"D","text":"维度评估：维度分数高低可以直接替代完整诊断。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“临床量表”和“剖面解释”。C、D是常见误区，不能作为规范理解或操作依据。')
