insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('4dcae8c2-78e7-5b8b-8c98-e1936c215c1e'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"人格病理：长期、广泛、僵化并导致显著痛苦或功能损害的人格体验和行为模式。"},{"key":"B","text":"维度评估：在连续维度上描述人格特质和功能严重度，保留个体差异和变化空间。"},{"key":"C","text":"诊断边界：测验报告可以自动生成最终诊断。"},{"key":"D","text":"人格病理反馈：直接宣告“你就是某型人格”，忽略不确定性。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“人格病理”和“维度评估”。C、D是常见误区，不能作为规范理解或操作依据。')
