insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('26e1089e-e5a6-5e40-9913-5ed8b0a3c36c'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'single', '围绕“人格病理”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"有某种特质或人际困难就等于人格障碍。"},{"key":"B","text":"评估跨情境稳定性、发展历史和功能损害。"},{"key":"C","text":"依据概念进行判断：长期、广泛、僵化并导致显著痛苦或功能损害的人格体验和行为模式。"},{"key":"D","text":"向来访者说明：人格病理需要看长期、跨情境和功能影响，不是一次困难或单个特质。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：有某种特质或人际困难就等于人格障碍。。规范依据是：长期、广泛、僵化并导致显著痛苦或功能损害的人格体验和行为模式。')
