insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('56e4c210-690d-59f7-854c-92f3414ef286'::uuid, '60f27810-dcbd-5a78-bcf2-f94f3d41936f'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"结果监测：在服务过程中重复使用适当指标追踪症状、功能、联盟和目标变化。"},{"key":"B","text":"被动数字数据：由手机、可穿戴设备或平台行为自动产生的活动、睡眠、生理或使用模式数据。"},{"key":"C","text":"多模态评估：数据来源越多，结论就自动越准确。"},{"key":"D","text":"算法偏差：算法是客观数学，因此不会有文化或社会偏差。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“结果监测”和“被动数字数据”。C、D是常见误区，不能作为规范理解或操作依据。')
