insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('59a12d5f-ac02-50cc-b8ad-273bcb1408e4'::uuid, '60f27810-dcbd-5a78-bcf2-f94f3d41936f'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"多模态评估：整合文本、语音、表情、生理和行为等多种数据来源形成评估信息。"},{"key":"B","text":"算法偏差：模型因训练样本、标签、特征和部署情境不公平而对不同群体产生系统误差。"},{"key":"C","text":"数字隐私：去掉姓名就完全没有重识别风险。"},{"key":"D","text":"专业责任：系统自动给出结果后咨询师无需检查或负责。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“多模态评估”和“算法偏差”。C、D是常见误区，不能作为规范理解或操作依据。')
