insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a2634a89-d464-59e7-a20c-61f44a1a246e'::uuid, '60f27810-dcbd-5a78-bcf2-f94f3d41936f'::uuid, 'blank', '请填写概念：____是指把评估本身作为合作性干预，通过共同问题、体验和反馈促进理解与改变。', NULL, '{"correct":["治疗性评估"]}'::jsonb, '答案是“治疗性评估”。')
